const items = $input.all();
const usersMap = {};

// 1. 建立客戶對照表
const customerMaster = {};
items.forEach(item => {
    if (item.json["編號"] && item.json["客戶名稱"]) {
        customerMaster[item.json["編號"]] = item.json["客戶名稱"];
    }
});

// 2. 處理 LINE ID 與編號比對
items.forEach(item => {
    const data = item.json;
    const userId = data["B:userId"];
    if (!userId || data["發送"] !== "馬年") return;

    const displayName = data["C:displayName"] || "親愛的客戶";

    if (!usersMap[userId]) {
        usersMap[userId] = {
            userId: userId,
            displayName: displayName,
            companies: new Set()
        };
    }

    for (let i = 1; i <= 10; i++) {
        const code = data[`編號${i}`];
        const company = customerMaster[code];

        if (company && company !== "未知公司") {
            const shouldSkip = company.includes("分公司") || company.includes("營業所") || company.includes("營業處");
            if (!shouldSkip) {
                usersMap[userId].companies.add(company);
            }
        }
    }
});

// 3. 輸出格式化
return Object.values(usersMap).map(user => {
    const finalCompanyList = user.companies.size > 0 
        ? Array.from(user.companies).join('\n') 
        : user.displayName;

    const flexJson = {
        "type": "bubble",
        "hero": {
            "type": "image",
            "url": "https://duk.tw/WxKLis.png",
            "size": "full",
            "aspectRatio": "20:10.9",
            "aspectMode": "fit"
        },
        "body": {
            "type": "box",
            "layout": "vertical",
            "contents": [
                {
                    "type": "box",
                    "layout": "horizontal",
                    "contents": [
                        { "type": "box", "layout": "vertical", "contents": [], "flex": 1 },
                        {
                            "type": "box",
                            "layout": "vertical",
                            "flex": 3,
                            "contents": [
                                { "type": "text", "text": "馬到成功", "weight": "bold", "size": "xxl", "color": "#D4AF37", "align": "start" },
                                { "type": "text", "text": "萬事如意", "weight": "bold", "size": "xxl", "color": "#D4AF37", "align": "end", "margin": "md" }
                            ]
                        },
                        { "type": "box", "layout": "vertical", "contents": [], "flex": 1 }
                    ]
                },
                {
                    "type": "box",
                    "layout": "vertical",
                    "margin": "lg",
                    "spacing": "sm",
                    "contents": [
                        { "type": "text", "text": finalCompanyList, "wrap": true, "weight": "bold", "size": "lg", "color": "#000000" },
                        { "type": "text", "text": "感謝您過去一年的支持與信任。在新的一年裡，祝福您如駿馬奔騰，事業蒸蒸日上，生活幸福安康！", "wrap": true, "size": "lg", "lineSpacing": "6px", "margin": "md" },
                        { "type": "separator", "margin": "xxl" },
                        {
                            "type": "box",
                            "layout": "vertical",
                            "margin": "md",
                            "contents": [
                                { "type": "text", "text": "【春節休假公告】", "size": "md", "color": "#C0392B", "weight": "bold" },
                                { "type": "text", "text": "本所於 2/14 ～ 2/22 春節休假\n2/23 (一) 正式上班", "size": "md", "color": "#555555", "wrap": true, "margin": "xs", "lineSpacing": "4px" }
                            ]
                        }
                    ]
                }
            ]
        },
        "footer": {
            "type": "box",
            "layout": "vertical",
            "spacing": "sm",
            "contents": [
                {
                    "type": "box",
                    "layout": "vertical", // 改為垂直分段
                    "contents": [
                        {
                            "type": "text",
                            "text": "廣伸記帳士事務所",
                            "size": "xl",
                            "color": "#C0392B",
                            "align": "center", // 置中顯示
                            "weight": "bold"
                        },
                        {
                            "type": "text",
                            "text": "全體同仁 敬上",
                            "size": "lg",
                            "color": "#C0392B",
                            "align": "center", // 置中顯示
                            "margin": "sm"
                        }
                    ]
                }
            ],
            "flex": 0
        },
        "styles": { "footer": { "separator": true } }
    };

    return {
        json: {
            userId: user.userId,
            displayName: user.displayName,
            flexMessage: flexJson
        }
    };
});

// 取得 LINE 節點傳過來的所有結果
const items = $input.all();
const count = items.length;

// 取得目前的日期時間
const now = new Date();
const dateStr = `${now.getFullYear()}/${now.getMonth() + 1}/${now.getDate()}`;

return {
    json: {
        totalSent: count,
        reportMessage: `📊 【自動發送報告】\n日期：${dateStr}\n內容：2026 新年賀卡 (馬年名單)\n狀態：執行成功 ✅\n總共發送人數：${count} 位客戶`
    }
};

// 取得所有傳入的項目
const allItems = $input.all();

// 遍歷所有項目並重新格式化
const results = allItems.map((item, index) => {
  return {
    json: {
      // 提取原始資料中的 B:userId 並命名為 searchId
      searchId: item.json["B:userId"],
      // 加入從 0 開始的索引序號
      index: index
    }
  };
});

return results;

// 1. 取得當前項目的原始資料
const input = $json; 

const clients = Array.isArray(input["客戶名稱"]) ? input["客戶名稱"] : [];
const amounts = Array.isArray(input["帳單金額"]) ? input["帳單金額"] : [];
const statuses = Array.isArray(input["狀態"]) ? input["狀態"] : [];
const links = Array.isArray(input["JPG連結"]) ? input["JPG連結"] : [];

// 取得總計金額與匯款帳號
const totalAmountRaw = Array.isArray(input["總金額"]) ? input["總金額"][0] : (input["總金額"] || "");
const bankAccount = Array.isArray(input["匯款帳號"]) ? input["匯款帳號"][0] : (input["匯款帳號"] || "暫無帳號資訊");

// --- 千分位格式化函式 ---
const formatPrice = (val) => {
  if (val === undefined || val === null || val === "" || isNaN(parseFloat(val))) return "--";
  return parseFloat(val).toLocaleString('en-US');
};

const pageSize = 4;
const bubbles = [];

// ==========================================
// 0. 第一個泡泡：專屬封面 
// ==========================================
bubbles.push({
  "type": "bubble",
  "size": "mega",
  "header": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      { "type": "text", "text": "🔔 帳單通知", "weight": "bold", "size": "xl", "color": "#111111" }
    ]
  },
  "body": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "麻煩您儘快核對帳單，如有錯誤請告知修正。\n\n匯款後請提供資訊以便對帳，感謝！\n\n👉 往右滑動可查看帳單明細與下載",
        "wrap": true,
        "size": "xl",
        "color": "#555555",
        "margin": "none"
      }
    ]
  },
  "footer": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "box",
        "layout": "vertical",
        "backgroundColor": "#F7F7F7",
        "paddingAll": "md",
        "cornerRadius": "sm",
        "contents": [
          { "type": "text", "text": "🏦 匯款帳號", "size": "sm", "color": "#888888", "weight": "bold" },
          { "type": "text", "text": bankAccount, "size": "lg", "color": "#111111", "weight": "bold", "wrap": true, "margin": "xs" }
        ]
      }
    ]
  }
});

// ==========================================
// 1. 後續泡泡：帳單明細 (迴圈產生)
// ==========================================
const isMultiPage = clients.length > pageSize;

for (let i = 0; i < clients.length; i += pageSize) {
  const currentBatch = clients.slice(i, i + pageSize);
  const isLastBubble = (i + pageSize) >= clients.length;  

  const rows = [];
  let pageSubtotal = 0; 

  const batchClientNames = currentBatch.join(',');
  const batchPostbackData = `action=download_bill&clients=${batchClientNames}`;

  // 構建該頁的客戶明細列表
  currentBatch.forEach((name, index) => {
    const realIndex = i + index;
    const isLastItemInBatch = index === currentBatch.length - 1; 

    let valAmount = amounts[realIndex];
    let displayAmount = formatPrice(valAmount);

    const rawStatus = String(statuses[realIndex] || "").trim();
    const rawLink = String(links[realIndex] || "").trim();

    const isNotIssued = rawLink === "尚未出帳" || String(valAmount).includes("#N/A");

    if (!isNotIssued && !isNaN(parseFloat(valAmount))) {
      pageSubtotal += parseFloat(valAmount);
    }

    let contentBox = [];
    if (isNotIssued) {
      contentBox = [
        { "type": "text", "text": name || "未知公司", "weight": "bold", "size": "lg", "color": "#111111", "wrap": false, "maxLines": 1 },
        { "type": "text", "text": "該用戶尚未出帳", "size": "sm", "color": "#999999", "margin": "xs", "style": "italic" }
      ];
    } else {
      // 將修改次數(狀態)與金額放在同一行 (次數在前，金額在後)
      const detailsLine = [];
      if (rawStatus !== "") {
        detailsLine.push({ "type": "text", "text": rawStatus, "size": "sm", "color": "#E67E22", "weight": "bold", "flex": 0 });
      }
      detailsLine.push({ "type": "text", "text": `金額：${displayAmount}`, "size": "sm", "color": "#666666", "flex": 1 });

      contentBox = [
        { "type": "text", "text": name || "未知公司", "weight": "bold", "size": "lg", "color": "#111111", "wrap": false, "maxLines": 1 },
        {
          "type": "box",
          "layout": "baseline",
          "margin": "xs",
          "spacing": "sm",
          "contents": detailsLine
        }
      ];
    }

    if (!isLastItemInBatch) {
      contentBox.push({ "type": "separator", "margin": "md" });
    }

    // 將每個公司的上下 margin 縮小，讓排版更緊湊
    rows.push({
      "type": "box",
      "layout": "vertical",
      "margin": "lg", 
      "spacing": "xs",
      "contents": contentBox
    });
  });

  // 每一頁共通底部：本頁小計
  rows.push({ "type": "separator", "margin": "xl", "color": "#eeeeee" });

  if (isMultiPage) {
    rows.push({
      "type": "box",
      "layout": "horizontal",
      "margin": "md",
      "contents": [
        { "type": "text", "text": "本頁小計", "size": "sm", "color": "#888888", "align": "start", "gravity": "center" },
        { "type": "text", "text": `NT$ ${formatPrice(pageSubtotal)}`, "size": "md", "weight": "bold", "color": "#111111", "align": "end" }
      ]
    });
  }

  // 最後一頁專屬區塊：總金額
  if (isLastBubble) {
    const hasTotalAmount = totalAmountRaw !== undefined && totalAmountRaw !== null && String(totalAmountRaw).trim() !== "";

    if (hasTotalAmount) {
      rows.push({ "type": "separator", "margin": "xl", "color": "#111111" });

      const formattedTotal = formatPrice(totalAmountRaw);
      rows.push(
        { "type": "text", "text": "合計總金額", "size": "sm", "color": "#888888", "align": "end", "margin": "md" },
        { 
          "type": "text", 
          "text": `NT$ ${formattedTotal}`, 
          "size": "xxl", 
          "weight": "bold", 
          "color": "#E63946", 
          "align": "end",
          "wrap": false,
          "adjustMode": "shrink-to-fit" 
        }
      );
    }
  }

  const pageIndex = (i / pageSize) + 1;
  const headerTitle = isMultiPage ? `📋 帳單明細 (${pageIndex})` : "📋 帳單明細";

  bubbles.push({
    "type": "bubble",
    "size": "mega",
    "header": {
      "type": "box",
      "layout": "vertical",
      "contents": [
        { "type": "text", "text": headerTitle, "weight": "bold", "size": "lg", "color": "#111111" }
      ]
    },
    "body": {
      "type": "box",
      "layout": "vertical",
      "contents": rows
    },
    // 將下載按鈕統一移至 footer 確保置底
    "footer": {
      "type": "box",
      "layout": "vertical",
      "contents": [
        {
          "type": "button",
          "action": { 
            "type": "postback", 
            "label": "帳單下載", 
            "data": batchPostbackData,
            "displayText": "帳單下載中，請稍後" 
          },
          "style": "primary", 
          "color": "#1DB446", 
          "height": "sm"
        }
      ]
    }
  });
}

return {
  flexJsonString: JSON.stringify({
    "type": "carousel",
    "contents": bubbles
  })
};

// 1. 取得 Aggregate8 輸出的資料
const data = items[0].json;

// 取得欄位
const ids = data["編號"] || [];
const customerNames = data["客戶名稱"] || [];
const mergeIds = data["合併客戶"] || [];
const searchIds = data["searchId"] || [];
const userIdsFromSheet = data["B:userId"] || data["userId"] || [];
const displayNames = data["C:displayName"] || data["displayName"] || [];

// 2. 建立 ID 對應姓名的查找表
const idToNameMap = {};
for (let i = 0; i < userIdsFromSheet.length; i++) {
    const id = String(userIdsFromSheet[i] || "").trim();
    const name = String(displayNames[i] || "").trim();
    if (id && name) {
        idToNameMap[id] = name;
    }
}

// 3. 進行資料分組
const groupByDisplayName = {};

for (let i = 0; i < searchIds.length; i++) {
    const sId = String(searchIds[i] || "").trim();
    const cName = customerNames[i];
    const itemId = ids[i];        // 該列的編號 (如 F01)
    const mId = mergeIds[i];      // 該列的合併客戶 (如 F01)

    const displayName = idToNameMap[sId] || sId;

    // --- 關鍵修正邏輯 ---
    // 從 displayName 擷取開頭的編號 (例如從 "F01生態松益-曾皇發" 擷取 "F01")
    const userPrefixMatch = displayName.match(/^[A-Z][0-9]+/);
    const userPrefix = userPrefixMatch ? userPrefixMatch[0] : null;

    // 只有當「編號」或「合併客戶」符合該人員的「員工編號前綴」時才加入
    if (userPrefix && (itemId === userPrefix || mId === userPrefix)) {
        if (!groupByDisplayName[displayName]) {
            groupByDisplayName[displayName] = new Set();
        }
        groupByDisplayName[displayName].add(cName);
    }
}

const keys = Object.keys(groupByDisplayName);

// --- 內容生成邏輯 (維持原樣) ---
let listContents = [
    { "type": "text", "text": "📊 發送報告摘要", "weight": "bold", "size": "lg", "color": "#111111" },
    { "type": "text", "text": `共計發送至 ${keys.length} 個帳號`, "size": "xs", "color": "#aaaaaa", "margin": "xs" },
    { "type": "separator", "margin": "lg" }
];

let tgText = "<b>📊 發送報告摘要</b>\n";
tgText += `<code>共計發送至 ${keys.length} 個帳號</code>\n\n`;

keys.forEach((displayName, index) => {
    const namesList = Array.from(groupByDisplayName[displayName]);

    tgText += `<b>🟢 ${displayName}</b>\n`;
    namesList.forEach(name => {
        tgText += `  • ${name}\n`;
    });
    tgText += "\n";

    listContents.push({
        "type": "box",
        "layout": "vertical",
        "margin": "lg",
        "contents": [
            { "type": "text", "text": displayName, "weight": "bold", "size": "sm", "color": "#1DB446", "wrap": true },
            {
                "type": "box",
                "layout": "vertical",
                "margin": "sm",
                "paddingStart": "sm",
                "contents": namesList.map(name => ({
                    "type": "text", "text": `• ${name}`, "size": "sm", "color": "#444444", "wrap": true, "margin": "xs"
                }))
            }
        ]
    });

    if (index < keys.length - 1) {
        listContents.push({ "type": "separator", "margin": "lg", "color": "#eeeeee" });
    }
});

return [{
    json: {
        flex_payload: JSON.stringify({ "type": "bubble", "body": { "type": "box", "layout": "vertical", "contents": listContents } }),
        telegram_text: tgText
    }
}];

// 1. 抓取伺服器時間 (對應您的工作流 HTTP Request6)
let amegoTime;
try {
  amegoTime = $("HTTP Request6").first().json.time.toString();
} catch (e) {
  amegoTime = Math.floor(Date.now() / 1000).toString();
}

// 2. API 認證資料
const appKey = 'sHeq7t8G1wiQvhAuIM27';
const SELLER_BAN = '12345678'; // 測試用統編

return $input.all().map(item => {
  const row = item.json;

  // 跳過沒有買方名稱的行
  if (!row['買方名稱']) return null;

  // --- 3. 關鍵計算：準備商品金額與稅務 ---
  // 從 Google Sheets 讀取資料
  const unitPrice = parseFloat(row['單價(含稅)']) || 0; // 假設為含稅單價
  const quantity = parseFloat(row['數量']) || 1;

  // 小計金額（優先使用表格中已計算的值，否則自動計算）
  const amountInput = parseFloat(row['小計金額(含稅)']);
  const amount = !isNaN(amountInput) ? Math.round(amountInput) : Math.round(unitPrice * quantity);

  // 買方統編處理
  const buyerBan = (row['買方統編'] && row['買方統編'].toString().trim() !== '') 
                   ? row['買方統編'].toString().trim() 
                   : '0000000000';

  // 判斷是否為 B2B（需要計算稅額）
  const isB2B = buyerBan !== '0000000000';

  // 計算銷售額和稅額
  let salesAmount = amount; // B2C 情況：銷售額 = 含稅總金額
  let taxAmount = 0;

  if (isB2B && amount > 0) {
    // B2B 情況：未稅銷售額 = 含稅總金額 / 1.05
    salesAmount = Math.round(amount / 1.05);
    taxAmount = amount - salesAmount; // 稅額 = 含稅總額 - 未稅銷售額
  }

  // --- 4. 構建符合 MIG 4.0 /json/f0401 的完整 JSON ---
  const dataObj = {
    // 基本訂單資訊
    "OrderId": (row['訂單編號'] || `ORDER_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`).toString().trim().substring(0, 40),
    "TrackApiCode": (row['指定字軌代碼'] || '').toString().trim(), // 選填

    // 買方資訊
    "BuyerIdentifier": buyerBan,
    "BuyerName": row['買方名稱'].toString().trim(),
    "BuyerAddress": (row['買方地址'] || '').toString().trim(),
    "BuyerTelephoneNumber": (row['買方電話'] || '').toString().trim(),
    "BuyerEmailAddress": (row['買方電子信箱'] || '').toString().trim(),

    // 發票註記與載具
    "MainRemark": (row['總備註(最多200個字)'] || '').toString().trim().substring(0, 200),

    // 載具相關（請根據您的業務需求調整）
    "CarrierType": (row['載具類別'] || '').toString().trim(), // 例如："", "3J0002", "amego"
    "CarrierId1": (row['載具顯碼'] || '').toString().trim(),
    "CarrierId2": (row['載具隱碼'] || '').toString().trim(),

    // 捐贈
    "NPOBAN": (row['捐贈對象'] || '').toString().trim(), // 捐贈碼

    // 商品明細（單一商品範例，可擴展為多商品）
    "ProductItem": [
      {
        "Description": (row['品名'] || '商品').toString().trim().substring(0, 256),
        "Quantity": quantity,
        "Unit": (row['單位'] || '式').toString().trim().substring(0, 6),
        "UnitPrice": unitPrice,
        "Amount": amount,
        "Remark": (row['備註'] || '').toString().trim().substring(0, 40),
        "TaxType": "1" // 1:應稅, 2:零稅率, 3:免稅
      }
    ],

    // --- 以下為必填的彙總金額字段 ---
    "SalesAmount": salesAmount,         // 應稅銷售額合計
    "FreeTaxSalesAmount": 0,            // 免稅銷售額合計
    "ZeroTaxSalesAmount": 0,            // 零稅率銷售額合計

    // 稅務資訊
    "TaxType": "1",                     // 課稅別（與商品一致）
    "TaxRate": "0.05",                  // 稅率
    "TaxAmount": taxAmount,             // 營業稅額
    "TotalAmount": amount,              // 發票總金額

    // --- 選填進階參數（根據需要啟用）---
    // "CustomsClearanceMark": 0,         // 通關方式註記（零稅率必填）
    // "ZeroTaxRateReason": 0,            // 零稅率原因（零稅率必填）
    // "BrandName": "",                   // 品牌名稱
    // "DetailVat": 1,                    // 0:未稅價 1:含稅價（預設）
    // "DetailAmountRound": 0,            // 0:小數7位 1:四捨五入整數
    // "PrinterType": 0,                  // 熱感應機型號
    // "PrinterLang": 0,                  // 編碼格式
    // "PrintDetail": 1                   // 是否列印明細
  };

  // --- 5. 準備 API 請求資料與簽名 ---
  const dataPayload = JSON.stringify(dataObj);
  const dataBase64 = Buffer.from(dataPayload, 'utf8').toString('base64');

  // 簽名字符串：data + time + APP Key（必須使用此順序）
  const raw_sign_string = dataBase64 + amegoTime + appKey;

  // --- 6. 輸出到下一個節點（MD5 加密）---
  return {
    json: {
      // API 基本參數
      invoice: SELLER_BAN,
      data: dataBase64,
      time: amegoTime,

      // 供 MD5 加密用的原始字符串
      raw_sign_string: raw_sign_string,

      // 除錯用（可選）
      _debug_dataObj: dataObj,
      _debug_dataPayload: dataPayload
    }
  };
}).filter(Boolean);

const item = $input.first();
console.log("時間戳記:", item.json.time);
console.log("Base64 Data:", item.json.data);
console.log("簽名字符串:", item.json.raw_sign_string);
console.log("解密後 JSON:", JSON.parse(Buffer.from(item.json.data, 'base64').toString()));
return item;

// 1. 抓取 Sheet 23 的資料 (建立合法 ID 清單)
const sheet23Items = $('Get row(s) in sheet23').all();
const validIds = new Set();
for (const item of sheet23Items) {
  const rawId = item.json['B:userId'] || item.json['userId'] || item.json['USERID'] || '';
  const uid = String(rawId).trim();
  if (uid) validIds.add(uid);
}

// 2. 抓取 Filter8 的資料
const filter8Items = $('Filter8').all();
const userButtonsMap = new Map();

for (const item of filter8Items) {
  const rawUserId = item.json['USERID'] || ''; 
  const invoiceUrl = item.json['11504發票'] || ''; 

  const customerName = item.json['客戶名稱'] || '查看電子發票';
  let buttonLabel = String(customerName);
  if (buttonLabel.length > 20) {
    buttonLabel = buttonLabel.substring(0, 19) + "…";
  }

  if (rawUserId && invoiceUrl) {
    const idList = String(rawUserId).split(/[，,;；\s\n]+/).map(id => id.trim()).filter(id => id);

    for (const id of idList) {
      if (validIds.has(id)) {
        if (!userButtonsMap.has(id)) {
          userButtonsMap.set(id, []);
        }

        userButtonsMap.get(id).push({
          "type": "button",
          "style": "primary",
          "height": "sm",
          "margin": "sm",
          "action": { 
            "type": "uri", 
            "label": buttonLabel, 
            "uri": invoiceUrl 
          },
          "color": "#1DB446"
        });
      }
    }
  }
}

// 3. 組合最終結果 (加入提醒事項與操作說明)
const results = [];

for (const [userId, buttonsArray] of userButtonsMap.entries()) {

  const flexContents = {
    "type": "bubble",
    "size": "mega",
    "body": {
      "type": "box",
      "layout": "vertical",
      "contents": [
        { "type": "text", "text": "🧾 電子發票通知", "weight": "bold", "color": "#1DB446", "size": "sm" },
        { "type": "text", "text": "電子發票證明聯", "weight": "bold", "size": "md", "margin": "lg", "wrap": true },
        { "type": "text", "text": "本所會再下一期主動扣抵\n不需額外印出送回", "size": "sm", "color": "#666666", "wrap": true, "margin": "sm" },

        // --- 澄清區塊 ---
        { "type": "separator", "margin": "lg" }, 
        { "type": "text", "text": "⚠️ 提醒事項", "weight": "bold", "size": "lg", "color": "#FF3B30", "margin": "lg" }, 
        { "type": "text", "text": "只有本所開的代辦費發票不用額外印回來，其他進項發票還是需要依照以前的作法處理喔！", "size": "sm", "color": "#333333", "wrap": true, "margin": "sm" },

        // --- 操作說明區塊 ---
        { "type": "separator", "margin": "lg" }, 
        { "type": "text", "text": "💡 點擊下方按鈕連結到電子發票檢視頁面\n再點擊「送出」即可查詢", "weight": "bold", "size": "sm", "color": "#1771c6", "wrap": true, "margin": "lg" }
      ]
    },
    "footer": {
      "type": "box",
      "layout": "vertical",
      "spacing": "sm",
      "contents": buttonsArray
    }
  };

  results.push({
    json: {
      "USERID": userId,
      "FlexMessage字串": JSON.stringify(flexContents)
    }
  });
}

return results;

// 取得傳入的字串內容
const rawData = $input.first().json.message.text; 

if (!rawData) return [];

// 1. 使用正則表達式取代特定的符號組合
// \*\* 匹配兩個星號
// \* \+ 匹配一個星號接一個加號 (加號在正則中是特殊字元，需加反斜線)
const ids = rawData
  .replace(/\*\*|\*\+/g, '') // 尋找並移除所有的 '**' 或 '*+'
  .split(/\r?\n/)
  .map(id => id.trim())
  .filter(id => id !== "");

// 轉換成 n8n 的多項目格式
return ids.map(id => {
  return {
    json: {
      searchId: id
    }
  };
});

// 1. 取得當前項目的原始資料
const input = $json; 

const clients = Array.isArray(input["客戶名稱"]) ? input["客戶名稱"] : [];
const amounts = Array.isArray(input["帳單金額"]) ? input["帳單金額"] : [];
const statuses = Array.isArray(input["狀態"]) ? input["狀態"] : [];
const links = Array.isArray(input["JPG連結"]) ? input["JPG連結"] : [];

// 取得總計金額與匯款帳號
const totalAmountRaw = Array.isArray(input["總金額"]) ? input["總金額"][0] : (input["總金額"] || "");
const bankAccount = Array.isArray(input["匯款帳號"]) ? input["匯款帳號"][0] : (input["匯款帳號"] || "暫無帳號資訊");

const pageSize = 4;
const bubbles = [];

const isMultiPage = clients.length > pageSize;

for (let i = 0; i < clients.length; i += pageSize) {
  const currentBatch = clients.slice(i, i + pageSize);
  const isLastBubble = (i + pageSize) >= clients.length;  

  const rows = [];
  let pageSubtotal = 0; 

  const batchClientNames = currentBatch.join(', ');
  // Postback 使用的資料內容
  const postbackData = `action=download_bill&clients=${batchClientNames}`;

  // 1. 構建客戶明細列表
  currentBatch.forEach((name, index) => {
    const realIndex = i + index;
    const isLastItemInBatch = index === currentBatch.length - 1; 

    let valAmount = amounts[realIndex];
    let displayAmount = (valAmount === undefined || valAmount === null || valAmount === "") ? "--" : String(valAmount);
    const rawStatus = String(statuses[realIndex] || " ");
    const rawLink = String(links[realIndex] || "").trim();

    const isNotIssued = rawLink === "尚未出帳" || displayAmount.includes("#N/A");

    if (!isNotIssued && !isNaN(parseFloat(valAmount))) {
      pageSubtotal += parseFloat(valAmount);
    }

    let contentBox = [];
    if (isNotIssued) {
      contentBox = [
        { "type": "text", "text": name || "未知公司", "weight": "bold", "size": "lg", "color": "#111111", "wrap": false, "maxLines": 1 },
        { "type": "text", "text": "該用戶尚未出帳", "size": "md", "color": "#999999", "margin": "sm", "style": "italic" }
      ];
    } else {
      let finalLink = rawLink || "https://www.google.com";
      if (finalLink.startsWith("http://")) {
        finalLink = finalLink.replace("http://", "https://");
      }
      const safeLink = encodeURI(finalLink);

      contentBox = [
        { "type": "text", "text": name || "未知公司", "weight": "bold", "size": "lg", "color": "#111111", "wrap": false, "maxLines": 1 },
        {
          "type": "box",
          "layout": "horizontal",
          "contents": [
            {
              "type": "box",
              "layout": "vertical",
              "flex": 2,
              "contents": [
                { "type": "text", "text": `金額：${displayAmount}`, "size": "md", "color": "#666666" },
                { "type": "text", "text": rawStatus, "size": "sm", "color": "#E67E22", "weight": "bold", "margin": "xs" }
              ]
            },
            {
              "type": "button",
              "action": { "type": "uri", "label": "帳單", "uri": safeLink },
              "flex": 1, "style": "primary", "color": "#1DB446", "height": "sm", "gravity": "center"
            }
          ]
        }
      ];
    }

    if (!isLastItemInBatch) {
      contentBox.push({ "type": "separator", "margin": "md" });
    }

    rows.push({
      "type": "box",
      "layout": "vertical",
      "margin": "lg",
      "spacing": "sm",
      "contents": contentBox
    });
  });

  // --- 處理「圖片下載」按鈕的位置 ---
  // A. 如果是多頁，按鈕放在「本頁小計」左邊，改為 postback
  if (isMultiPage) {
    rows.push(
      { "type": "separator", "margin": "xl", "color": "#eeeeee" },
      {
        "type": "box",
        "layout": "horizontal",
        "margin": "md",
        "spacing": "md",
        "contents": [
          {
            "type": "button",
            "action": { 
              "type": "postback", 
              "label": "帳單下載", 
              "data": postbackData
            },
            "style": "primary", "color": "#1DB446", "height": "sm", "flex": 2, "gravity": "center"
          },
          {
            "type": "box",
            "layout": "vertical",
            "flex": 3,
            "contents": [
              { "type": "text", "text": "本頁小計", "size": "xs", "color": "#888888", "align": "end" },
              { "type": "text", "text": `NT$ ${pageSubtotal.toLocaleString()}`, "size": "md", "weight": "bold", "color": "#111111", "align": "end" }
            ]
          }
        ]
      }
    );
  }

  // B. 底部「總計金額」區塊 (僅限最後一個泡泡)
  if (isLastBubble) {
    const footerContents = [];
    const hasTotalAmount = totalAmountRaw !== undefined && totalAmountRaw !== null && String(totalAmountRaw).trim() !== "";

    if (hasTotalAmount) {
      footerContents.push({ "type": "separator", "margin": "xl", "color": "#111111" });

      // 如果不是多頁，按鈕要放在合計左邊，改為 postback
      if (!isMultiPage) {
        footerContents.push({
          "type": "box",
          "layout": "horizontal",
          "margin": "md",
          "spacing": "md",
          "contents": [
            {
              "type": "button",
              "action": { 
                "type": "postback", 
                "label": "帳單下載", 
                "data": postbackData
              },
              "style": "primary", "color": "#1DB446", "height": "sm", "flex": 2, "gravity": "center"
            },
            {
              "type": "box",
              "layout": "vertical",
              "flex": 3,
              "contents": [
                { "type": "text", "text": "合計總金額", "size": "sm", "color": "#888888", "align": "end" },
                { "type": "text", "text": `NT$ ${totalAmountRaw}`, "size": "xl", "weight": "bold", "color": "#E63946", "align": "end" }
              ]
            }
          ]
        });
      } else {
        // 多頁時的合計顯示
        footerContents.push(
          { "type": "text", "text": "合計總金額", "size": "lg", "color": "#888888", "align": "end", "margin": "md" },
          { "type": "text", "text": `NT$ ${totalAmountRaw}`, "size": "xxl", "weight": "bold", "color": "#E63946", "align": "end" }
        );
      }
    }

    // 匯款資訊區塊
    footerContents.push({
      "type": "box",
      "layout": "vertical",
      "margin": "xl",
      "backgroundColor": "#F7F7F7",
      "paddingAll": "md",
      "cornerRadius": "sm",
      "contents": [
        { "type": "text", "text": "🏦 匯款帳號", "size": "xs", "color": "#888888", "weight": "bold" },
        { "type": "text", "text": bankAccount, "size": "lg", "color": "#111111", "weight": "bold", "wrap": true, "margin": "xs" },
        { "type": "text", "text": "麻煩您儘快核對帳單，如有錯誤請告知修正。匯款後請提供資訊以便對帳，感謝！", "size": "xs", "color": "#555555", "wrap": true, "margin": "md" }
      ]
    });

    rows.push({ 
      "type": "box", 
      "layout": "vertical", 
      "contents": footerContents 
    });
  }

  const pageIndex = (i / pageSize) + 1;
  const headerTitle = isMultiPage ? `📋 帳單明細 (${pageIndex})` : "📋 帳單明細";

  bubbles.push({
    "type": "bubble",
    "size": "mega",
    "header": {
      "type": "box",
      "layout": "vertical",
      "contents": [
        { "type": "text", "text": headerTitle, "weight": "bold", "size": "lg", "color": "#111111" }
      ]
    },
    "body": {
      "type": "box",
      "layout": "vertical",
      "contents": rows
    }
  });
}

return {
  flexJsonString: JSON.stringify({
    "type": "carousel",
    "contents": bubbles
  })
};

// 在每筆 item 上加一個 index 欄位
const newItems = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  newItems.push({
    json: {
      ...item.json,
      index: i,   // 第幾筆，從 0 開始
    },
  });
}

return newItems;

