for (const item of $input.all()) {
  try {
    // 假設你的 Google Sheets 欄位名稱叫做 JSON_Content
    // 將純文字轉為 JSON 物件
    const parsedFlex = JSON.parse(item.json.JSON_Content);

    // 將轉換後的結果存入一個新的欄位叫做 linePayload
    item.json.linePayload = {
      "type": "flex",
      "altText": "您有一則新訊息",
      "contents": parsedFlex
    };
  } catch (error) {
    // 預防表格內 JSON 格式寫錯導致流程中斷
    item.json.linePayload = {
      "type": "text",
      "text": "資料庫 JSON 格式錯誤，請檢查 Google Sheets。"
    };
  }
}
return $input.all();

