// 1. 取得經過 Merge 完美配對的資料
const allItems = $input.all();
const groupByDisplayName = {};

// 2. 直接根據姓名將公司分組
allItems.forEach(item => {
    const d = item.json;

    // 取得這行的姓名與公司
    const name = d["C:displayName"] || d["displayName"] || "未知用戶";
    const company = d["客戶名稱"];

    if (company) {
        if (!groupByDisplayName[name]) {
            groupByDisplayName[name] = new Set();
        }
        groupByDisplayName[name].add(company);
    }
});

const keys = Object.keys(groupByDisplayName);

// 3. 生成 Telegram 訊息內容
let tgText = "<b>📊 發送報告摘要</b>\n";
tgText += `<code>共計發送至 ${keys.length} 個帳號</code>\n\n`;

// 生成 Line Flex 訊息 (預留)
let listContents = [
    { "type": "text", "text": "📊 發送報告摘要", "weight": "bold", "size": "lg", "color": "#111111" },
    { "type": "text", "text": `共計發送至 ${keys.length} 個帳號`, "size": "xs", "color": "#aaaaaa", "margin": "xs" },
    { "type": "separator", "margin": "lg" }
];

keys.forEach((displayName, index) => {
    const namesList = Array.from(groupByDisplayName[displayName]);

    // 組合 Telegram
    tgText += `<b>🟢 ${displayName}</b>\n`;
    namesList.forEach(name => {
        tgText += `  • ${name}\n`;
    });
    tgText += "\n";

    // 組合 Line
    listContents.push({
        "type": "box",
        "layout": "vertical",
        "margin": "lg",
        "contents": [
            { "type": "text", "text": displayName, "weight": "bold", "size": "sm", "color": "#1DB446", "wrap": true },
            {
                "type": "box",
                "layout": "vertical",
                "margin": "sm",
                "paddingStart": "sm",
                "contents": namesList.map(name => ({
                    "type": "text", "text": `• ${name}`, "size": "sm", "color": "#444444", "wrap": true, "margin": "xs"
                }))
            }
        ]
    });

    if (index < keys.length - 1) {
        listContents.push({ "type": "separator", "margin": "lg", "color": "#eeeeee" });
    }
});

// 4. 輸出給後續節點 (Telegram / Line 推送節點)
return [{
    json: {
        flex_payload: JSON.stringify({ 
            "type": "bubble", 
            "body": { "type": "box", "layout": "vertical", "contents": listContents } 
        }),
        telegram_text: tgText,
        account_count: keys.length
    }
}];

// 取得所有傳入的項目
const allItems = $input.all();

// 遍歷所有項目並重新格式化
const results = allItems.map((item, index) => {
  return {
    json: {
      // 提取原始資料中的 B:userId 並命名為 searchId
      searchId: item.json["B:userId"],
      // 加入從 0 開始的索引序號
      index: index
    }
  };
});

return results;

// 1. 取得當前項目的原始資料
const input = $json; 

const clients = Array.isArray(input["客戶名稱"]) ? input["客戶名稱"] : [];
const amounts = Array.isArray(input["帳單金額"]) ? input["帳單金額"] : [];
const statuses = Array.isArray(input["狀態"]) ? input["狀態"] : [];
const links = Array.isArray(input["JPG連結"]) ? input["JPG連結"] : [];

// 取得匯款帳號（移除原本調用總金額的 totalAmountRaw）
let bankAccount = Array.isArray(input["匯款帳號"]) ? input["匯款帳號"][0] : (input["匯款帳號"] || "暫無帳號資訊");

// ★ 修正核心：將「北中壢分行」後方的空格（不論有無）強制替換為換行符號 \n
bankAccount = bankAccount.replace(/(北中壢分行)\s*/, "$1\n");

// --- 千分位格式化函式 ---
const formatPrice = (val) => {
  if (val === undefined || val === null || val === "" || isNaN(parseFloat(val))) return "--";
  return parseFloat(val).toLocaleString('en-US');
};

const pageSize = 4; // 設定每頁最多顯示幾家公司
const bubbles = [];

// ==========================================
// ★ 全域檢查是否「有任何一筆」帳單尚未出帳
// ★ 同時：自動計算所有客戶的「合計總金額」
// ==========================================
let anyNotIssued = false;
let calculatedTotalAmount = 0; // 新增：用來儲存計算出來的總金額

for (let j = 0; j < clients.length; j++) {
  const checkAmt = amounts[j];
  const checkLink = String(links[j] || "").trim();
  const isNotIssued = checkLink === "尚未出帳" || String(checkAmt).includes("#N/A");

  if (isNotIssued) {
    anyNotIssued = true;
    // 注意：這裡不使用 break 了，因為要讓迴圈跑完才能正確加總所有客戶的金額
  }

  // 如果這筆帳單正常出帳，且金額是數字，就加進總金額
  if (!isNotIssued && !isNaN(parseFloat(checkAmt))) {
    calculatedTotalAmount += parseFloat(checkAmt);
  }
}

// ==========================================
// 產生「包含所有客戶」的 Postback Data
// ==========================================
const allClientNames = clients.join(',');
const allPostbackData = `action=download_bill&clients=${allClientNames}`;

// ==========================================
// 0. 第一個泡泡：專屬封面 
// ==========================================
bubbles.push({
  "type": "bubble",
  "size": "mega",
  "header": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      { "type": "text", "text": "🔔 帳單通知", "weight": "bold", "size": "xl", "color": "#111111" }
    ]
  },
  "body": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "麻煩您儘快核對帳單，如有錯誤請告知修正。\n匯款後請提供資訊以便對帳，感謝！\n\n👉 往右滑動可查看費用總覽，點擊綠色按鈕下載全部帳單。",
        "wrap": true,
        "size": "xl",
        "color": "#555555",
        "margin": "none"
      }
    ]
  },
  "footer": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "box",
        "layout": "vertical",
        "backgroundColor": "#F7F7F7",
        "paddingAll": "md",
        "cornerRadius": "sm",
        "contents": [
          { "type": "text", "text": "🏦 匯款帳號", "size": "sm", "color": "#888888", "weight": "bold" },
          { "type": "text", "text": bankAccount, "size": "lg", "color": "#111111", "weight": "bold", "wrap": true, "margin": "xs" }
        ]
      }
    ]
  }
});

// ==========================================
// 1. 後續泡泡：自動分頁與帳單總覽
// ==========================================
const isMultiPage = clients.length > pageSize;

for (let i = 0; i < clients.length; i += pageSize) {
  const currentBatch = clients.slice(i, i + pageSize);
  const isLastBubble = (i + pageSize) >= clients.length;  

  const rows = [];
  let pageSubtotal = 0; 

  currentBatch.forEach((name, index) => {
    const realIndex = i + index;
    const isLastItemInBatch = index === currentBatch.length - 1; 

    let valAmount = amounts[realIndex];
    let displayAmount = formatPrice(valAmount);

    const rawStatus = String(statuses[realIndex] || "").trim();
    const rawLink = String(links[realIndex] || "").trim();

    const isNotIssued = rawLink === "尚未出帳" || String(valAmount).includes("#N/A");

    if (!isNotIssued && !isNaN(parseFloat(valAmount))) {
      pageSubtotal += parseFloat(valAmount);
    }

    let contentBox = [];
    if (isNotIssued) {
      contentBox = [
        { "type": "text", "text": name || "未知公司", "weight": "bold", "size": "lg", "color": "#111111", "wrap": true },
        { "type": "text", "text": "該用戶尚未出帳", "size": "sm", "color": "#999999", "margin": "xs", "style": "italic" }
      ];
    } else {
      const detailsLine = [];
      if (rawStatus !== "") {
        detailsLine.push({ "type": "text", "text": rawStatus, "size": "sm", "color": "#E67E22", "weight": "bold", "flex": 0 });
      }
      detailsLine.push({ "type": "text", "text": `金額：${displayAmount}`, "size": "sm", "color": "#666666", "flex": 1 });

      contentBox = [
        { "type": "text", "text": name || "未知公司", "weight": "bold", "size": "lg", "color": "#111111", "wrap": true },
        {
          "type": "box",
          "layout": "baseline",
          "margin": "xs",
          "spacing": "sm",
          "contents": detailsLine
        }
      ];
    }

    if (!isLastItemInBatch) {
      contentBox.push({ "type": "separator", "margin": "md" });
    }

    rows.push({
      "type": "box",
      "layout": "vertical",
      "margin": "lg", 
      "spacing": "xs",
      "contents": contentBox
    });
  });

  rows.push({ "type": "separator", "margin": "xl", "color": "#eeeeee" });

  if (isMultiPage) {
    rows.push({
      "type": "box",
      "layout": "horizontal",
      "margin": "md",
      "contents": [
        { "type": "text", "text": "本頁小計", "size": "sm", "color": "#888888", "align": "start", "gravity": "center" },
        { "type": "text", "text": `NT$ ${formatPrice(pageSubtotal)}`, "size": "md", "weight": "bold", "color": "#111111", "align": "end" }
      ]
    });
  }

  // ★ 修改處：最後一頁直接顯示計算出來的總金額
  if (isLastBubble) {
    rows.push({ "type": "separator", "margin": "xl", "color": "#111111" });

    // 直接調用剛剛算好的 calculatedTotalAmount
    const formattedTotal = formatPrice(calculatedTotalAmount);
    rows.push(
      { "type": "text", "text": "合計總金額", "size": "sm", "color": "#888888", "align": "end", "margin": "md" },
      { 
        "type": "text", 
        "text": `NT$ ${formattedTotal}`, 
        "size": "xxl", 
        "weight": "bold", 
        "color": "#E63946", 
        "align": "end",
        "wrap": false,
        "adjustMode": "shrink-to-fit" 
      }
    );
  }

  const pageIndex = (i / pageSize) + 1;
  const headerTitle = isMultiPage ? `📋 帳單總覽 (${pageIndex})` : "📋 帳單總覽";

  const bubble = {
    "type": "bubble",
    "size": "mega",
    "header": {
      "type": "box",
      "layout": "vertical",
      "contents": [
        { "type": "text", "text": headerTitle, "weight": "bold", "size": "lg", "color": "#111111" }
      ]
    },
    "body": {
      "type": "box",
      "layout": "vertical",
      "contents": rows
    }
  };

  if (isLastBubble && !anyNotIssued) {
    bubble.footer = {
      "type": "box",
      "layout": "vertical",
      "contents": [
        {
          "type": "button",
          "action": { 
            "type": "postback", 
            "label": "下載全部帳單", 
            "data": allPostbackData,
            "displayText": "正在下載帳單，請稍候..." 
          },
          "style": "primary", 
          "color": "#1DB446", 
          "height": "sm"
        }
      ]
    };
  }

  bubbles.push(bubble);
}

return {
  flexJsonString: JSON.stringify({
    "type": "carousel",
    "contents": bubbles
  })
};

const allItems = $input.all();
const items = allItems.map(item => item.json);

// 1. 建立「編號 -> 公司名稱」的查詢字典 (從帳單明細中提取)
// 例如: codeToCompany["C30"] = "良品出版社有限公司"
const codeToCompany = {};
items.forEach(d => {
    if (d["編號"] && d["客戶名稱"]) {
        codeToCompany[d["編號"].trim()] = d["客戶名稱"].trim();
    }
});

// 2. 處理每個聯絡人，根據編號1~10去找對應的公司名稱
const personToCompanies = {};

items.forEach(d => {
    // 如果這筆資料有聯絡人名稱 (代表它是上方的名單資料)
    if (d["C:displayName"]) {
        const displayName = d["C:displayName"];

        if (!personToCompanies[displayName]) {
            personToCompanies[displayName] = new Set();
        }

        // 自動檢查 編號1 到 編號10
        for (let i = 1; i <= 10; i++) {
            const codeKey = `編號${i}`;
            const codeVal = d[codeKey];

            // 如果該欄位有填寫代碼 (例如 "C30", "C31")
            if (codeVal && typeof codeVal === 'string' && codeVal.trim() !== "") {
                const cleanCode = codeVal.trim();
                // 去字典裡面找對應的公司名稱
                const companyName = codeToCompany[cleanCode];

                // 如果有找到對應的公司，就加入清單中
                if (companyName) {
                    personToCompanies[displayName].add(companyName);
                }
            }
        }
    }
});

// 3. 準備輸出給 Telegram 的文字
// 只過濾出名下確實有對應到公司的聯絡人
const keys = Object.keys(personToCompanies).filter(k => personToCompanies[k].size > 0);
const totalAccounts = keys.length;

let tgText = "<b>📊 發送報告摘要</b>\n";
tgText += `<code>共計發送至 ${totalAccounts} 個帳號</code>\n\n`;

keys.forEach(displayName => {
    tgText += `<b>🟢 ${displayName}</b>\n`;

    // 把 Set 轉回 Array，列出該名下所有公司
    const companyList = Array.from(personToCompanies[displayName]);
    companyList.forEach(company => {
        tgText += `  • ${company}\n`;
    });
    tgText += "\n";
});

// 4. 輸出最終結果
return [{
    json: {
        telegram_text: tgText,
        account_count: totalAccounts
    }
}];

