const formatPrice = (val) => {
  if (val === undefined || val === null || val === "" || isNaN(parseFloat(val))) return "--";
  return parseFloat(val).toLocaleString('en-US');
};

for (const userItem of sendList) {
  const searchId = userItem.json["B:userId"] || userItem.json["userId"];
  const displayName = userItem.json["C:displayName"] || userItem.json["displayName"] || searchId;

  if (!searchId) continue;

  // 1. 記憶體內比對：找出該用戶的帳單 (USERID 1~10)
  const userBills = allBills.filter(bill => {
    for (let i = 1; i <= 10; i++) {
      if (String(bill.json[`USERID-${i}`]).trim() === String(searchId).trim()) return true;
    }
    return false;
  });

  if (userBills.length === 0) continue;

  // ==========================================
  // 【新增邏輯】根據客戶名稱合併重複帳單並加總金額
  // ==========================================
  const mergedBillsMap = {};
  userBills.forEach(b => {
    const companyName = String(b.json["客戶名稱"] || "未知公司").trim();
    const amountRaw = b.json["帳單金額"];
    const amountNum = parseFloat(amountRaw);
    const rawLink = String(b.json["JPG連結"] || "").trim();
    const isNotIssued = rawLink === "尚未出帳" || String(amountRaw).includes("#N/A");

    if (!mergedBillsMap[companyName]) {
      // 第一次出現此公司
      mergedBillsMap[companyName] = {
        name: companyName,
        amount: (!isNotIssued && !isNaN(amountNum)) ? amountNum : 0,
        status: String(b.json["狀態"] || "").trim(),
        isNotIssued: isNotIssued
      };
    } else {
      // 已有相同公司，累加金額
      if (!isNotIssued && !isNaN(amountNum)) {
        mergedBillsMap[companyName].amount += amountNum;
      }
      // 只要任一筆已出帳，即視為已出帳
      if (!isNotIssued) {
        mergedBillsMap[companyName].isNotIssued = false;
      }
      // 若原本無狀態但新的一筆有，則覆蓋
      if (mergedBillsMap[companyName].status === "" && String(b.json["狀態"] || "").trim() !== "") {
        mergedBillsMap[companyName].status = String(b.json["狀態"] || "").trim();
      }
    }
  });

  // 將整理後的 Map 轉換回陣列，供後續卡片生成使用
