  const clients = mergedBills.map(b => b.name);

  const totalAmountRaw = userBills[0].json["總金額"] || "";
  const bankAccount = userBills[0].json["匯款帳號"] || "暫無帳號資訊";

  const pageSize = 4;
  const bubbles = [];

  // 1. 封面泡泡
  bubbles.push({
    "type": "bubble", "size": "mega",
    "header": { "type": "box", "layout": "vertical", "contents": [ { "type": "text", "text": "🔔 帳單通知", "weight": "bold", "size": "xl", "color": "#111111" } ] },
    "body": { "type": "box", "layout": "vertical", "contents": [ { "type": "text", "text": "麻煩您儘快核對帳單，如有錯誤請告知修正。\n\n匯款後請提供資訊以便對帳，感謝！\n\n👉 往右滑動可查看帳單明細與下載", "wrap": true, "size": "xl", "color": "#555555" } ] },
    "footer": { "type": "box", "layout": "vertical", "contents": [ { "type": "box", "layout": "vertical", "backgroundColor": "#F7F7F7", "paddingAll": "md", "cornerRadius": "sm", "contents": [ { "type": "text", "text": "🏦 匯款帳號", "size": "sm", "color": "#888888", "weight": "bold" }, { "type": "text", "text": bankAccount, "size": "lg", "color": "#111111", "weight": "bold", "wrap": true, "margin": "xs" } ] } ] }
  });

  // 2. 明細泡泡 (改為讀取合併後的 mergedBills)
  const isMultiPage = clients.length > pageSize;
  for (let i = 0; i < clients.length; i += pageSize) {
    const currentBatch = clients.slice(i, i + pageSize);
