          { "type": "text", "text": name || "未知公司", "weight": "bold", "size": "lg", "color": "#111111", "maxLines": 1 },
          { "type": "text", "text": "該用戶尚未出帳", "size": "sm", "color": "#999999", "margin": "xs", "style": "italic" }
        ];
