        ];
      }
      if (!isLastItemInBatch) contentBox.push({ "type": "separator", "margin": "md" });
      rows.push({ "type": "box", "layout": "vertical", "margin": "lg", "spacing": "xs", "contents": contentBox });
    });

    rows.push({ "type": "separator", "margin": "xl", "color": "#eeeeee" });
    if (isMultiPage) rows.push({ "type": "box", "layout": "horizontal", "margin": "md", "contents": [ { "type": "text", "text": "本頁小計", "size": "sm", "color": "#888888", "align": "start", "gravity": "center" }, { "type": "text", "text": `NT$ ${formatPrice(pageSubtotal)}`, "size": "md", "weight": "bold", "color": "#111111", "align": "end" } ] });

    if (isLastBubble && totalAmountRaw) {
      rows.push({ "type": "separator", "margin": "xl", "color": "#111111" });
      rows.push(
        { "type": "text", "text": "合計總金額", "size": "sm", "color": "#888888", "align": "end", "margin": "md" },
        { "type": "text", "text": `NT$ ${formatPrice(totalAmountRaw)}`, "size": "xxl", "weight": "bold", "color": "#E63946", "align": "end", "adjustMode": "shrink-to-fit" }
      );
    }

    bubbles.push({
      "type": "bubble", "size": "mega",
      "header": { "type": "box", "layout": "vertical", "contents": [ { "type": "text", "text": isMultiPage ? `📋 帳單明細 (${(i / pageSize) + 1})` : "📋 帳單明細", "weight": "bold", "size": "lg", "color": "#111111" } ] },
      "body": { "type": "box", "layout": "vertical", "contents": rows },
      "footer": { "type": "box", "layout": "vertical", "contents": [ { "type": "button", "action": { "type": "postback", "label": "帳單下載", "data": batchPostbackData, "displayText": "帳單下載中，請稍後" }, "style": "primary", "color": "#1DB446", "height": "sm" } ] }
    });
  }

  // ==========================================
  // 【修改邏輯】利用 Set 排除重複的編號，再加入 toUpdateRows
  // ==========================================
  adminReportData.push({ displayName, clients });
  userBills.forEach(b => {
    const billId = b.json["編號"];
    if (billId && !seenUpdateIds.has(billId)) {
      seenUpdateIds.add(billId); // 記下這個編號
      toUpdateRows.push({ "編號": billId, "狀態": "完成" });
    }
  });

  results.push({
    json: {
      searchId,
      displayName,
      flexJsonString: JSON.stringify({ "type": "carousel", "contents": bubbles })
    }
  });
}

// 3. 準備管理者報表 (附加在第一筆資料中帶往後方)
if (results.length > 0) {
  let telegram_text = "<b>📊 發送報告摘要</b>\n<code>共計發送至 " + adminReportData.length + " 個帳號</code>\n\n";
  const listContents = [
    { "type": "text", "text": "📊 發送報告摘要", "weight": "bold", "size": "lg", "color": "#111111" },
    { "type": "text", "text": `共計發送至 ${adminReportData.length} 個帳號`, "size": "xs", "color": "#aaaaaa", "margin": "xs" },
    { "type": "separator", "margin": "lg" }
  ];

  adminReportData.forEach((data, index) => {
    telegram_text += `<b>🟢 ${data.displayName}</b>\n`;
    data.clients.forEach(c => telegram_text += `  • ${c}\n`);
    telegram_text += "\n";
    listContents.push({
      "type": "box", "layout": "vertical", "margin": "lg",
      "contents": [
        { "type": "text", "text": data.displayName, "weight": "bold", "size": "sm", "color": "#1DB446", "wrap": true },
        { "type": "box", "layout": "vertical", "margin": "sm", "paddingStart": "sm", "contents": data.clients.map(c => ({ "type": "text", "text": `• ${c}`, "size": "sm", "color": "#444444", "wrap": true, "margin": "xs" })) }
      ]
    });
    if (index < adminReportData.length - 1) listContents.push({ "type": "separator", "margin": "lg", "color": "#eeeeee" });
  });

  results[0].json.telegram_text = telegram_text;
  results[0].json.flex_payload = JSON.stringify({ "type": "bubble", "body": { "type": "box", "layout": "vertical", "contents": listContents } });
  results[0].json.allUpdates = toUpdateRows;
}

return results;

// ==========================================
// 1. 共用核心函式 (Flex Message 產生器)
// ==========================================
const pageSize = 4; // 每頁最多顯示的公司數量

const formatPrice = (val) => {
  if (val === undefined || val === null || val === "" || isNaN(parseFloat(val))) return "--";
  return parseFloat(val).toLocaleString('en-US');
};

function generateFlexCarousel(clients, amounts, statuses, links, bankAccountRaw, displayName = "") {
  let bankAccount = bankAccountRaw || "暫無帳號資訊";
  bankAccount = bankAccount.replace(/(北中壢分行)\s*/, "$1\n");

  let anyNotIssued = false;
  let calculatedTotalAmount = 0;

  for (let j = 0; j < clients.length; j++) {
    const checkAmt = amounts[j];
    const checkLink = String(links[j] || "").trim();
    const isNotIssued = checkLink === "尚未出帳" || String(checkAmt).includes("#N/A");
    if (isNotIssued) anyNotIssued = true;
    if (!isNotIssued && !isNaN(parseFloat(checkAmt))) {
      calculatedTotalAmount += parseFloat(checkAmt);
    }
  }

  const allClientNames = clients.join(',');
  const allPostbackData = `action=download_bill&clients=${allClientNames}`;
  const bubbles = [];

  bubbles.push({
    "type": "bubble", "size": "mega",
    "header": { "type": "box", "layout": "vertical", "contents": [{ "type": "text", "text": "🔔 帳單通知", "weight": "bold", "size": "xl", "color": "#111111" }] },
    "body": { "type": "box", "layout": "vertical", "contents": [{ "type": "text", "text": "麻煩您儘快核對帳單，如有錯誤請告知修正。\n匯款後請提供資訊以便對帳，感謝！\n\n👉 往右滑動可查看費用總覽，點擊綠色按鈕下載全部帳單。", "wrap": true, "size": "xl", "color": "#555555" }] },
    "footer": { "type": "box", "layout": "vertical", "contents": [{ "type": "box", "layout": "vertical", "backgroundColor": "#F7F7F7", "paddingAll": "md", "cornerRadius": "sm", "contents": [{ "type": "text", "text": "🏦 匯款帳號", "size": "sm", "color": "#888888", "weight": "bold" }, { "type": "text", "text": bankAccount, "size": "lg", "color": "#111111", "weight": "bold", "wrap": true, "margin": "xs" }] }] }
  });

  const isMultiPage = clients.length > pageSize;
  for (let i = 0; i < clients.length; i += pageSize) {
    const currentBatch = clients.slice(i, i + pageSize);
    const isLastBubble = (i + pageSize) >= clients.length;
    const rows = [];
    let pageSubtotal = 0;

    currentBatch.forEach((name, index) => {
      const realIndex = i + index;
      const isLastItemInBatch = index === currentBatch.length - 1;
      let valAmount = amounts[realIndex];
      let displayAmount = formatPrice(valAmount);
      const rawStatus = String(statuses[realIndex] || "").trim();
      const rawLink = String(links[realIndex] || "").trim();
      const isNotIssued = rawLink === "尚未出帳" || String(valAmount).includes("#N/A");

      if (!isNotIssued && !isNaN(parseFloat(valAmount))) pageSubtotal += parseFloat(valAmount);

      let contentBox = [];
      if (isNotIssued) {
        contentBox = [
          { "type": "text", "text": name || "未知公司", "weight": "bold", "size": "lg", "color": "#111111", "wrap": true },
          { "type": "text", "text": "該用戶尚未出帳", "size": "sm", "color": "#999999", "margin": "xs", "style": "italic" }
        ];
      } else {
        const detailsLine = [];
        if (rawStatus !== "") detailsLine.push({ "type": "text", "text": rawStatus, "size": "sm", "color": "#E67E22", "weight": "bold", "flex": 0 });
        detailsLine.push({ "type": "text", "text": `金額：${displayAmount}`, "size": "sm", "color": "#666666", "flex": 1 });
        contentBox = [
          { "type": "text", "text": name || "未知公司", "weight": "bold", "size": "lg", "color": "#111111", "wrap": true },
          { "type": "box", "layout": "baseline", "margin": "xs", "spacing": "sm", "contents": detailsLine }
        ];
      }
      if (!isLastItemInBatch) contentBox.push({ "type": "separator", "margin": "md" });
      rows.push({ "type": "box", "layout": "vertical", "margin": "lg", "spacing": "xs", "contents": contentBox });
    });

    rows.push({ "type": "separator", "margin": "xl", "color": "#eeeeee" });
    if (isMultiPage) rows.push({ "type": "box", "layout": "horizontal", "margin": "md", "contents": [{ "type": "text", "text": "本頁小計", "size": "sm", "color": "#888888", "gravity": "center" }, { "type": "text", "text": `NT$ ${formatPrice(pageSubtotal)}`, "size": "md", "weight": "bold", "color": "#111111", "align": "end" }] });
    if (isLastBubble) {
      rows.push({ "type": "separator", "margin": "xl", "color": "#111111" });
      rows.push(
        { "type": "text", "text": "合計總金額", "size": "sm", "color": "#888888", "align": "end", "margin": "md" },
        { "type": "text", "text": `NT$ ${formatPrice(calculatedTotalAmount)}`, "size": "xxl", "weight": "bold", "color": "#E63946", "align": "end", "adjustMode": "shrink-to-fit" }
      );
    }

    const pageIndex = (i / pageSize) + 1;
    const headerTitle = isMultiPage ? `📋 帳單總覽 (${pageIndex})` : "📋 帳單總覽";
    const bubble = { "type": "bubble", "size": "mega", "header": { "type": "box", "layout": "vertical", "contents": [{ "type": "text", "text": headerTitle, "weight": "bold", "size": "lg", "color": "#111111" }] }, "body": { "type": "box", "layout": "vertical", "contents": rows } };
    if (isLastBubble && !anyNotIssued) {
      bubble.footer = { "type": "box", "layout": "vertical", "contents": [{ "type": "button", "action": { "type": "postback", "label": "下載全部帳單", "data": allPostbackData, "displayText": "正在下載帳單，請稍候..." }, "style": "primary", "color": "#1DB446", "height": "sm" }] };
    }
    bubbles.push(bubble);
  }
  return JSON.stringify({ "type": "carousel", "contents": bubbles });
}

// ==========================================
// 2. 自動偵測執行模式 (Mode A 或 Mode B)
// ==========================================
let isModeA = false;
let triggerData = null;

try {
  // 嘗試讀取 LINE Trigger，如果有 replyToken 代表是客戶主動查詢 (Mode A)
  triggerData = $('Line Messaging Trigger').first()?.json;
  if (triggerData && triggerData.replyToken) {
    isModeA = true;
  }
} catch (e) {
  // 如果找不到 LINE Trigger，代表是後台批次推送 (Mode B)
  isModeA = false;
}

// ==========================================
// 3. 取得「所有帳單明細」 (兩種模式都需要，且統一過濾空白)
// ==========================================
const allBills = $input.all()
  .map(item => item.json)
  .filter(b => b["編號"] && String(b["編號"]).trim() !== "");

// ==========================================
// 4. 依照模式執行對應邏輯
// ==========================================

if (isModeA) {
  // ------------ 【模式 A：客戶主動查詢】 ------------
  let userId = triggerData.source.userId;
  let replyToken = triggerData.replyToken;
  let userInfo = null;
  let resultStatus = 'success';
  let flexJsonString = '';

  try {
    userInfo = $('取得客戶LINE_ID資料').first()?.json || null;
  } catch (e) { }

  if (!userInfo || userInfo['帳單權限'] === 'N') {
    resultStatus = 'no_permission';
  } else {
    const validCodes = new Set();
    for (let i = 1; i <= 10; i++) {
      const codeVal = userInfo[`編號${i}`];
      if (codeVal && String(codeVal).trim() !== "") validCodes.add(String(codeVal).trim());
    }

    const today = new Date();
    const currentDay = today.getDate();
    const isDateValid = currentDay >= 1 && currentDay <= 25;

    if (validCodes.size === 0 || !isDateValid) {
      resultStatus = 'not_bound';
    } else {
      const matchedBills = allBills.filter(bill => validCodes.has(String(bill['編號']).trim()));

      if (matchedBills.length === 0) {
        resultStatus = 'not_bound';
      } else {
        const clients = matchedBills.map(b => b["客戶名稱"]);
        const amounts = matchedBills.map(b => b["帳單金額"]);
        const statuses = matchedBills.map(b => b["狀態"]);
        const links = matchedBills.map(b => b["JPG連結"]);
        const bankAccountRaw = matchedBills[0]["匯款帳號"];
        const displayName = userInfo["C:displayName"] || userInfo["displayName"] || "";

        flexJsonString = generateFlexCarousel(clients, amounts, statuses, links, bankAccountRaw, displayName);
      }
    }
  }

  // 回傳給 Switch 節點
  return [{
    json: {
      mode: "A_Client_Query",
      userId: userId,
      replyToken: replyToken,
      status: resultStatus,
      flexJsonString: flexJsonString
    }
  }];

} else {
  // ------------ 【模式 B：後台主動推送批次處理】 ------------
  let paidContacts = [];
  try {
    paidContacts = $('取得OK頁面').all()
      .map(item => item.json)
      .filter(contact => {
        const uId = contact["B:userId"] || contact["userId"];
        return uId && String(uId).trim() !== "";
      });
  } catch(e) {
    throw new Error("模式 B 執行失敗：找不到 '取得OK頁面' 節點的資料");
  }

  const billMap = {};
  allBills.forEach(b => {
    if (b["編號"]) billMap[String(b["編號"]).trim()] = b;
  });

  const lineTasks = [];
  const personToCompanies = {};
  const updateCodesSet = new Set();
  const groupedContacts = {};

  // 歸戶與編號去重
  paidContacts.forEach(contact => {
    const userId = contact["B:userId"] || contact["userId"];
    if (!userId) return;

    if (!groupedContacts[userId]) {
      groupedContacts[userId] = {
        userId: userId,
        displayName: contact["C:displayName"] || contact["displayName"],
        allCodes: new Set()
      };
    }

    for (let i = 1; i <= 10; i++) {
      const codeVal = contact[`編號${i}`];
      if (codeVal && String(codeVal).trim() !== "") {
        groupedContacts[userId].allCodes.add(String(codeVal).trim());
      }
    }
  });

  // 生成每位用戶的 Flex Message
  Object.values(groupedContacts).forEach(userGroup => {
    const userId = userGroup.userId;
    const displayName = userGroup.displayName;
    const matchedBills = [];

    userGroup.allCodes.forEach(cleanCode => {
      const matchedBill = billMap[cleanCode];
      if (matchedBill) {
        matchedBills.push(matchedBill);
        updateCodesSet.add(cleanCode);
        if (displayName && matchedBill["客戶名稱"]) {
          if (!personToCompanies[displayName]) personToCompanies[displayName] = new Set();
          personToCompanies[displayName].add(matchedBill["客戶名稱"].trim());
        }
      }
    });

    if (matchedBills.length === 0) return;

    const clients = matchedBills.map(b => b["客戶名稱"]);
    const amounts = matchedBills.map(b => b["帳單金額"]);
    const statuses = matchedBills.map(b => b["狀態"]);
    const links = matchedBills.map(b => b["JPG連結"]);
    const bankAccountRaw = matchedBills[0]["匯款帳號"];

    const flexJsonString = generateFlexCarousel(clients, amounts, statuses, links, bankAccountRaw, displayName);

    lineTasks.push({ userId: userId, flexJsonString: flexJsonString });
  });

  // 建立 Telegram 報告摘要
  const tgKeys = Object.keys(personToCompanies).filter(k => personToCompanies[k].size > 0);
  let tgText = "<b>📊 發送報告摘要</b>\n";
  tgText += `<code>共計發送至 ${tgKeys.length} 個帳號</code>\n\n`;
  tgKeys.forEach(name => {
    tgText += `<b>🟢 ${name}</b>\n`;
    Array.from(personToCompanies[name]).forEach(company => {
      tgText += ` • ${company}\n`;
    });
    tgText += "\n";
  });

  const updateList = Array.from(updateCodesSet).map(code => ({ json: { "編號": code } }));

  // 回傳給 Split Out 節點
  return [{
    json: {
      mode: "B_Backend_Push",
      lineTasks: lineTasks,
      tgText: tgText,
      updateList: updateList
    }
  }];
}

