parameters.jsCode:
const item = $input.first().json;
const results = [];

// 檢查 1 到 10 的編號欄位
for (let i = 1; i <= 10; i++) {
  const id = item[`編號${i}`];

  // 如果有值，且不是空白字串，才加入查詢清單
  if (id && typeof id === 'string' && id.trim() !== "") {
    results.push({ json: { "有效客戶編號": id.trim() } });
  }
}

// 如果都沒綁定編號，防呆中斷
if (results.length === 0) {
  throw new Error("此帳號未綁定任何客戶編號");
}

return results;

// 取得 Aggregate 聚合後的資料
const data = $json;

// 1. 跨節點安全地獲取最源頭的 userId
let userId = "";

// 優先：從當前輸入（資料橋接傳過來的）獲取 userId
if (data.userId && String(data.userId).trim() !== "") {
  userId = String(data.userId).trim();
}

// 備用 A：嘗試從最源頭的 LINE Trigger 節點獲取 userId
if (!userId) {
  try {
    const triggerData = $('Line Messaging Trigger').first()?.json || {};
    if (triggerData.source && triggerData.source.userId) {
      userId = triggerData.source.userId;
    }
  } catch (e) {
    // 忽略找不到節點的錯誤
  }
}

// 備用 B：嘗試回頭去 Code in JavaScript9 拿 userId
if (!userId) {
  try {
    const code9Data = $('Code in JavaScript9').first()?.json || {};
    userId = code9Data.userId || (code9Data.lineTasks && code9Data.lineTasks[0]?.userId) || "";
  } catch (e) {
    // 忽略找不到節點的錯誤
  }
}

// 2. 將連結陣列轉換為 LINE 的 Image Messages 格式
const urls = Array.isArray(data.JPG連結) ? data.JPG連結 : [];
const allMessages = urls.map(url => {
  const secureUrl = String(url).replace("http://", "https://");
  return {
    "type": "image",
    "originalContentUrl": secureUrl,
    "previewImageUrl": secureUrl
  };
});

const results = [];
const chunkSize = 5; // LINE API 限制每次最多 5 個物件

// 3. 切割陣列，分批處理（一律強制使用 Push API，不使用 replyToken）
for (let i = 0; i < allMessages.length; i += chunkSize) {
  const chunk = allMessages.slice(i, i + chunkSize);
  if (chunk.length === 0) continue;

  if (userId && userId.trim() !== "") {
    results.push({
      json: {
        endpoint: "https://api.line.me/v2/bot/message/push", // 100% 使用 Push API
        lineBody: {
          to: userId.trim(),
          messages: chunk
        }
      }
    });
  }
}

return results;

// 回頭精準撈取 Code in JavaScript9 的資料
const code9 = $('Code in JavaScript9').first()?.json || {};
const trigger = $('Line Messaging Trigger').first()?.json || {}; // 抓取當下的 userId

return [{
  json: {
    clientNames: code9.clientNames || [],
    userId: trigger.source?.userId || code9.userId || ""
  }
}];

