// 取得最源頭的「已繳費名單」
const paidList = $('取得已繳費名單1').all();
// 取得前一個節點抓下來的「全部帳單明細」
const allBills = $input.all();

const updateMap = new Map();

// 遍歷所有已付款的客戶名單
for (const user of paidList) {
  const searchId = user.json["B:userId"] || user.json["userId"];
  if (!searchId) continue;

  // 在記憶體中快速搜尋 USERID-1 ~ USERID-10 是否符合
  const matchingBills = allBills.filter(bill => {
    for (let i = 1; i <= 10; i++) {
      if (String(bill.json[`USERID-${i}`] || "").trim() === String(searchId).trim()) return true;
    }
    return false;
  });

  // 取出編號準備更新，並利用 Map 自動剔除重複的編號
  for (const bill of matchingBills) {
    const id = bill.json["編號"];
    if (id && !updateMap.has(id)) {
      updateMap.set(id, { "編號": id, "狀態": "已繳" });
    }
  }
}

const updates = Array.from(updateMap.values());

// 如果沒有任何資料需要更新，直接終止後續流程
if (updates.length === 0) return [];

// 組裝 Telegram 報告文字
let message = "📋 *今日繳費清單總覽*\n";
message += "--------------------------\n";
updates.forEach(u => {
  message += `🔹 編號：${u["編號"]} | 狀態：${u["狀態"]}\n`;
});
message += "--------------------------\n";
message += `共計：${updates.length} 筆資料`;

// 輸出報告文字與要更新的陣列
return [{
  json: {
    combinedMessage: message,
    allUpdates: updates
  }
}];

// 取得所有傳入的項目
const allItems = $input.all();

// 遍歷所有項目並重新格式化
const results = allItems.map((item, index) => {
  return {
    json: {
      // 提取原始資料中的 B:userId 並命名為 searchId
      searchId: item.json["B:userId"],
      // 加入從 0 開始的索引序號
      index: index
    }
  };
});

return results;

