return items.map((item, index) => {
  const data = item.json;
  const rawDate = data["收帳"] || "____/____";
  const userId = data["B:userId"];

  // 格式化日期：將 05/20 轉換成 05 月 20 日
  const formattedDate = rawDate.includes("/") 
    ? rawDate.replace("/", " 月 ") + " 日" 
    : rawDate;

  // 將注意事項轉成 LINE Flex Message 的 text 區塊
  const noticeContents = noticeList.map((text, idx) => ({
    "type": "text",
    "text": text,
    "size": "md",
    "color": "#333333",
    "wrap": true,
    ...(idx > 0 ? { "margin": "sm" } : {})
  }));

  // 回傳標準 n8n 格式
  return {
    json: {
      ...data,
      index: index,              // 第幾筆資料（從 0 開始）
      notices: noticeList,       // 保留注意事項陣列
      userId: userId,            // 供後續 LINE 節點使用
      flexMessage: {
