// 遍歷所有項目並重新格式化
const results = allItems.map((item, index) => {
  return {
    json: {
      // 提取原始資料中的 B:userId 並命名為 searchId
      searchId: item.json["B:userId"],
      // 加入從 0 開始的索引序號
      index: index
    }
  };
});

return results;

// 1. 取得 B 欄位的 LINE User ID
const itemJson = $input.item.json;
const userId = itemJson["B:userId"] || itemJson.B || itemJson.userId || "";

// 2. 取得當前日期 (台灣時區)
const now = new Date();
const taiwanDateStr = now.toLocaleDateString('zh-TW', { timeZone: 'Asia/Taipei', year: 'numeric', month: '2-digit', day: '2-digit' });
const [ceYearStr, monthStr, dayStr] = taiwanDateStr.split('/');

const currentCEYear = parseInt(ceYearStr, 10);
const currentROCYear = currentCEYear - 1911; // 轉民國年
const currentMonth = parseInt(monthStr, 10);
const currentDay = parseInt(dayStr, 10);

// 3. 計算【結算申報書】年份 (5/31前為前前年，6/1起為前一年)
let taxReturnROCYear = (currentMonth < 5 || (currentMonth === 5 && currentDay <= 31)) 
  ? currentROCYear - 2 
  : currentROCYear - 1;

// 4. 計算【營業稅 401 報表】期別
let vatStartROCYear = currentROCYear;
let vatEndROCYear = currentROCYear;
let lastCompletedEndMonth = 0;

if (currentMonth % 2 === 1) { 
  lastCompletedEndMonth = (currentDay >= 15) ? currentMonth - 1 : currentMonth - 3;
} else { 
  lastCompletedEndMonth = currentMonth - 2;
}

if (lastCompletedEndMonth <= 0) {
  lastCompletedEndMonth += 12;
  vatEndROCYear -= 1;
  vatStartROCYear -= 1;
}

const pad = (n) => n.toString().padStart(2, '0');
const vatPeriodStr = (vatStartROCYear === vatEndROCYear)
  ? `${vatStartROCYear}年01-${pad(lastCompletedEndMonth)}月`
  : `${vatStartROCYear}年01月~${vatEndROCYear}年${pad(lastCompletedEndMonth)}月`;

// 5. 組成純文字內容
const plainTextMessage = `如需將帳務轉入本所，麻煩請協助準備以下資料：
