3: 發票購買證正本
4: ${taxReturnROCYear}年結算申報書（損益表、資產負債表、財產目錄、成本表、股利分配表）
5: ${vatPeriodStr}401報表、繳款書正本、傳票和原始憑證
6: 負責人、股東雙證件影本
7: 如有其他文件將另行通知

※ 上述資料如有已經提供過的部分，請自動忽略。`;

// 6. 組成 Flex Message 物件
const flexObj = {
  type: "bubble",
  header: {
    type: "box",
    layout: "vertical",
    backgroundColor: "#1DB446",
    contents: [
      {
        type: "text",
        text: "帳務轉入資料準備清單",
        weight: "bold",
        color: "#FFFFFF",
        size: "lg"
      }
    ]
  },
  body: {
    type: "box",
    layout: "vertical",
    spacing: "md",
    contents: [
      {
        type: "text",
        text: "如需將帳務轉入本所，麻煩請協助準備以下資料：",
        wrap: true,
        size: "md",
        weight: "bold",
        color: "#333333"
      },
      { type: "separator" },
      {
        type: "box",
        layout: "vertical",
        spacing: "sm",
        contents: [
          { type: "text", text: "1. 最新登記事項表、章程、股東名簿", wrap: true, size: "sm" },
          { type: "text", text: "2. 統一發票章、公司大小章", wrap: true, size: "sm" },
          { type: "text", text: "3. 發票購買證正本", wrap: true, size: "sm" },
          { type: "text", text: `4. ${taxReturnROCYear}年結算申報書（損益表、資產負債表、財產目錄、成本表、股利分配表）`, wrap: true, size: "sm" },
          { type: "text", text: `5. ${vatPeriodStr}401報表、繳款書正本、傳票和原始憑證`, wrap: true, size: "sm", weight: "bold", color: "#1DB446" },
          { type: "text", text: "6. 負責人、股東雙證件影本", wrap: true, size: "sm" },
          { type: "text", text: "7. 如需其他文件將另行通知", wrap: true, size: "sm" }
        ]
      }
    ]
  },
  footer: {
    type: "box",
    layout: "vertical",
    backgroundColor: "#FFEBEE",
    paddingAll: "10px",
    contents: [
      {
        type: "text",
        text: "※ 上述資料如有已經提供過的部分，請自動忽略。",
        wrap: true,
        size: "xs",
        color: "#E53935",
        align: "center",
        weight: "bold"
      }
    ]
  }
};

// 7. 回傳 JSON 字串給 LineMessaging 節點使用
return [{
  json: {
    userId: userId,
    plainTextMessage: plainTextMessage,
    flexJsonString: JSON.stringify(flexObj)
  }
}];

