// 1. 取得上一個節點 (Aggregate 節點) 的資料
const input = items[0].json;

// 確保資料為陣列格式
const clients = Array.isArray(input.client_name) ? input.client_name : [input.client_name];
const folderLinks = Array.isArray(input.client_folder) ? input.client_folder : [input.client_folder];
const uids = Array.isArray(input.Uid) ? input.Uid : [input.Uid];

// 2. 取得 Line Messaging Trigger 的 userId
const userId = $node["Line Messaging Trigger"].json.source.userId;

// 3. 將資料合併並根據 Uid 排序
// 把分散的資料壓成一個個物件，方便排序
let clientList = clients.map((name, index) => {
  return {
    name: name,
    link: folderLinks[index] || "",
    uid: uids[index] || ""
  };
});

// 執行排序 (根據 Uid 進行字母與數字升冪排序，如 A21 會排在 B66 前面)
clientList.sort((a, b) => a.uid.localeCompare(b.uid, undefined, { numeric: true, sensitivity: 'base' }));

// 4. 動態生成按鈕
const buttons = clientList.map((item) => {
  const link = item.link;

  // 串接 uid 參數邏輯
  const finalUri = link.includes('?') 
    ? `${link}&uid=${userId}` 
    : `${link}?uid=${userId}`;

  return {
    "type": "button",
    "action": {
      "type": "uri",
      // 在標籤前面加上 UID，方便辨識，例如: "A21 廣伸企業有限公司"
      "label": String(item.name).substring(0, 40),
      "uri": finalUri
    },
    "style": "primary",
    "margin": "md",
    "color": "#00B900"
  };
});

// 5. 組裝 Flex Message
const flexContent = {
  "type": "bubble",
  "header": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "📁 雲端資料夾存取",
        "weight": "bold",
        "size": "lg",
        "color": "#1DB446"
      }
    ]
  },
  "body": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "所屬單位的資料夾連結：",
        "size": "lg",
        "color": "#666666",
        "wrap": true,
        "margin": "none"
      },
      {
        "type": "box",
        "layout": "vertical",
        "margin": "lg",
        "spacing": "sm",
        "contents": buttons
      }
    ]
  },
  "footer": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "如誤按請忽略此訊息",
        "size": "md",
        "color": "#FF0000",
        "align": "center"
      }
    ]
  }
};

return {
  flexJsonString: JSON.stringify(flexContent)
};

// 1. 6 位同仁的真實姓名與專屬 Email 對照表
const employeeConfig = {
  "A": { name: "王淑娥", email: "0916714339@kscpb.com" },
  "B": { name: "黃紋綺", email: "ks112@kscpb.com" },
  "C": { name: "張玉幸", email: "ks113@kscpb.com" },
  "D": { name: "黎依婷", email: "ks117@kscpb.com" },
  "E": { name: "余秋萍", email: "ks115@kscpb.com" },
  "F": { name: "周佳玲", email: "ks116@kscpb.com" }
};

// 向上追溯抓取兩個 Sheets 節點的完整資料
const sheetDetails = $('Get row(s) in sheet4').all();   // 明細表 (總表分頁，含有明細及發獎日期)
const sheetDeductions = $('Get row(s) in sheet1').all(); // 扣款表 (總獎金分頁，含有橫向勞健保欄位)

// 基礎篩選：明細表必須是「是否已發 === V」且有「發獎日期」
const validItems = sheetDetails.filter(item => {
  return item.json["是否已發"] === "V" && item.json["發獎日期"];
});

// 2. 核心功能：若遇到假日則自動提早發放的函數
function getActualPayDate(dateStr) {
  const dateParts = dateStr.split('/');
  if (dateParts.length !== 3) return null;

  let checkDate = new Date(parseInt(dateParts[0], 10), parseInt(dateParts[1], 10) - 1, parseInt(dateParts[2], 10));
  checkDate.setHours(0, 0, 0, 0);

  const dayOfWeek = checkDate.getDay(); // 0 是週日，6 是週六

  if (dayOfWeek === 6) { 
    checkDate.setDate(checkDate.getDate() - 1); // 週六 -> 提早到週五
  } else if (dayOfWeek === 0) { 
    checkDate.setDate(checkDate.getDate() - 2); // 週日 -> 提早到週五
  }

  return checkDate;
}

// 3. 獲取當前系統時間並找出最接近的未來實際發薪日
const today = new Date();
today.setHours(0, 0, 0, 0);

const upcomingDates = [];
const dateMap = {}; 

validItems.forEach(item => {
  const originalDateStr = item.json["發獎日期"]; 
  const actualPayDate = getActualPayDate(originalDateStr);

  if (actualPayDate && actualPayDate >= today) {
    const yyyy = actualPayDate.getFullYear();
    const mm = String(actualPayDate.getMonth() + 1).padStart(2, '0');
    const dd = String(actualPayDate.getDate()).padStart(2, '0');
    const formattedKey = `${yyyy}/${mm}/${dd}`;

    if (!upcomingDates.includes(formattedKey)) {
      upcomingDates.push(formattedKey);
    }
    dateMap[formattedKey] = originalDateStr;
  }
});

if (upcomingDates.length === 0) {
  return [{ json: { message: "目前沒有未來即將發放的薪資明細資料。" } }];
}

upcomingDates.sort((a, b) => new Date(a) - new Date(b));
const targetActualPayDate = upcomingDates[0]; // 最接近的實際發薪日 (如 "2026/07/24")
const targetOriginalDate = dateMap[targetActualPayDate]; // 試算表原始日期 (如 "2026/07/25")

// 4. 動態對照扣款表（Sheet1）中該日期對應的各區欄位資料
// 尋找與此次發獎日期一致的那一列扣款資料
const targetDeductionRow = sheetDeductions.find(item => {
  return item.json["發獎日期"] === targetOriginalDate || item.json["發獎日期"] === targetActualPayDate;
});

// 5. 分組加總明細
const combinedGroups = {};

validItems.forEach(item => {
  const data = item.json;
  if (data["發獎日期"] !== targetOriginalDate) return; 

  const code = data["編號"];
  if (!code || typeof code !== 'string') return;

  const groupLetter = code.charAt(0).toUpperCase();
  if (!employeeConfig[groupLetter]) return;

  if (!combinedGroups[groupLetter]) {
    combinedGroups[groupLetter] = {
      actualPayDate: targetActualPayDate, 
      groupLetter: groupLetter,
      records: []
    };
  }
  combinedGroups[groupLetter].records.push(data);
});

const outputItems = [];

// 6. 打包產出同仁的獨立 HTML 表格
for (const group in combinedGroups) {
  const groupData = combinedGroups[group];
  const formattedDate = groupData.actualPayDate; 
  const records = groupData.records;
  const config = employeeConfig[group];

  let total_account_fee = 0;
  let total_other = 0;
  let total_extra = 0;
  let total_dividend = 0;
  let total_settle = 0;
  let total_salary = 0;
  let tableRowsHTML = "";

  records.forEach((data, index) => {
    const account_fee = Number(data["帳費"]) || 0;
    const other = Number(data["其他"]) || 0;
    const extra = Number(data["加收補收"]) || 0;
    const dividend = Number(data["股利分配"]) || 0;
    const settle = Number(data["結算決算"]) || 0;
    const salary = Math.round(account_fee * 0.4); 

    total_account_fee += account_fee;
    total_other += other;
    total_extra += extra;
    total_dividend += dividend;
    total_settle += settle;
    total_salary += salary;

    const rowBgColor = index % 2 === 1 ? 'background-color: #e0e0e0;' : 'background-color: #ffffff;';

    tableRowsHTML += `
      <tr style="${rowBgColor} font-size: 13pt;">
        <td style="border: 1px solid #000; padding: 6px; text-align: left;">${data["期數"] || ''}</td>
        <td style="border: 1px solid #000; padding: 6px; text-align: left;">${data["編號"] || ''}</td>
        <td style="border: 1px solid #000; padding: 6px; text-align: left;">${data["客戶"] || ''}</td>
        <td style="border: 1px solid #000; padding: 6px; text-align: right;">${account_fee.toLocaleString()}</td>
        <td style="border: 1px solid #000; padding: 6px; text-align: right;">${other > 0 ? other.toLocaleString() : ''}</td>
        <td style="border: 1px solid #000; padding: 6px; text-align: right;">${extra > 0 ? extra.toLocaleString() : ''}</td>
        <td style="border: 1px solid #000; padding: 6px; text-align: right;">${dividend > 0 ? dividend.toLocaleString() : ''}</td>
        <td style="border: 1px solid #000; padding: 6px; text-align: right;">${settle > 0 ? settle.toLocaleString() : ''}</td>
        <td style="border: 1px solid #000; padding: 6px; text-align: right; font-weight: bold;">${salary.toLocaleString()}</td>
      </tr>
    `;
  });

  // 核心改動：直接從選定日期那一列中，動態抓取該同仁分區代號後綴的欄位 (例如：勞保A, 健保A...)
  let labor_insurance = 0;
  let health_insurance = 0;
  let received_amount = 0;
  let deduction_other = 0;

  if (targetDeductionRow) {
    const d = targetDeductionRow.json;
    labor_insurance = Number(d[`勞保${group}`]) || 0;  
    health_insurance = Number(d[`健保${group}`]) || 0; 
    received_amount = Number(d[`已領${group}`]) || 0; 
    deduction_other = Number(d[`其他${group}`]) || 0;
  }

  // 實發金額計算 (因為試算表填入的值本身已帶有負號如 -1476，所以用加法即可正確扣除)
  const actual_pay = total_salary + labor_insurance + health_insurance + received_amount + deduction_other;
  const periodDisplay = records[0]["期數"] || "本期";

  const finalHTML = `
  <div style="font-family: 'Microsoft JhengHei', Arial, sans-serif; max-width: 900px; margin: auto; padding: 10px; color: #000;">
    <p>親愛的 <b>${config.name}</b> 同仁您好：以下為您將於 <b>${formattedDate} (遇假日提早發放)</b> 之薪資明細總表。</p>

    <!-- 上方總計看板區 -->
    <table style="width: 100%; border-collapse: collapse; margin-bottom: 20px; font-size: 13pt;">
      <tr>
        <td style="width: 12%; padding: 4px;">客戶分區</td>
        <td style="width: 20%; padding: 4px; background-color: #fce4d6; border: 1px solid #b7b7b7; text-align: center; font-weight: bold;">${group}</td>
        <td style="width: 15%; padding: 4px; text-align: right;">應領薪資</td>
        <td style="width: 13%; padding: 4px; text-align: right; font-weight: bold;">${total_salary.toLocaleString()}</td>
        <td style="width: 10%; padding: 4px; text-align: right;">勞保</td>
        <td style="width: 10%; padding: 4px; text-align: right;">健保</td>
        <td style="width: 10%; padding: 4px; text-align: right;">已領</td>
        <td style="width: 10%; padding: 4px; text-align: right;">其他</td>
        <td style="width: 12%; padding: 4px; text-align: right;">實發</td>
      </tr>
      <tr>
        <td style="padding: 4px;">發薪日期</td>
        <td style="padding: 4px; background-color: #fce4d6; border: 1px solid #b7b7b7; text-align: center;">${formattedDate}</td>
        <td style="padding: 4px; text-align: right;"></td>
        <td style="padding: 4px; text-align: right; font-size: 14pt; font-weight: bold;">${total_salary.toLocaleString()}</td>
        <td style="padding: 4px; text-align: right; color: red;">${labor_insurance.toLocaleString()}</td>
        <td style="padding: 4px; text-align: right; color: red;">${health_insurance.toLocaleString()}</td>
        <td style="padding: 4px; text-align: right; color: red;">${received_amount.toLocaleString()}</td>
        <td style="padding: 4px; text-align: right; color: red;">${deduction_other !== 0 ? deduction_other.toLocaleString() : ''}</td>
        <td style="padding: 4px; text-align: right; font-size: 14pt; font-weight: bold;">${actual_pay.toLocaleString()}</td>
      </tr>
      <tr>
        <td style="padding: 4px;">所屬期數</td>
        <td style="padding: 4px; background-color: #fce4d6; border: 1px solid #b7b7b7; text-align: center;">${periodDisplay}</td>
        <td colspan="7"></td>
      </tr>
    </table>

    <!-- 下方明細表格 -->
    <table style="width: 100%; border-collapse: collapse; text-align: center; border: 2px solid #000;">
      <tr style="background-color: #ffffff; font-size: 13pt;">
        <th rowspan="2" style="border: 1px solid #000; padding: 8px; width: 14%;">期數</th>
