// 2. 自動提早發放機制 (遇假日提早至週五)
function getActualPayDate(dateStr) {
  if (!dateStr) return null;
  const dateParts = dateStr.split('/');
  if (dateParts.length !== 3) return null;

  let checkDate = new Date(parseInt(dateParts[0], 10), parseInt(dateParts[1], 10) - 1, parseInt(dateParts[2], 10));
  checkDate.setHours(0, 0, 0, 0);

  const dayOfWeek = checkDate.getDay();
  if (dayOfWeek === 6) checkDate.setDate(checkDate.getDate() - 1);
  else if (dayOfWeek === 0) checkDate.setDate(checkDate.getDate() - 2);

  return checkDate;
}

// 輔助函數：解析單列應領薪資 (優先抓 M 欄/合計，無則用 40% 計算)
function getRowSalary(data) {
  const account_fee = Number(data["帳費"]) || 0;
  const rawTotal = data["合計"] ?? data["M"]; 

  if (rawTotal !== undefined && rawTotal !== "" && rawTotal !== null) {
    const parsed = Number(String(rawTotal).replace(/,/g, '').trim());
    if (!isNaN(parsed)) return parsed;
  }

  // 若無 M 欄數值，則使用 40% 預設試算
  return Math.round(account_fee * 0.4);
}

// 3. 計算目標發薪日
const today = new Date();
today.setHours(0, 0, 0, 0);

const validItems = sheetDetails.filter(item => item.json["是否已發"] === "V" && item.json["發獎日期"]);
const upcomingDates = [];
const dateMap = {}; 

validItems.forEach(item => {
  const originalDateStr = item.json["發獎日期"]; 
  const actualPayDate = getActualPayDate(originalDateStr);

  if (actualPayDate && actualPayDate >= today) {
    const yyyy = actualPayDate.getFullYear();
    const mm = String(actualPayDate.getMonth() + 1).padStart(2, '0');
    const dd = String(actualPayDate.getDate()).padStart(2, '0');
    const formattedKey = `${yyyy}/${mm}/${dd}`;

    if (!upcomingDates.includes(formattedKey)) upcomingDates.push(formattedKey);
    dateMap[formattedKey] = originalDateStr;
  }
});

if (upcomingDates.length === 0) {
  return [{ json: { message: "目前沒有未來即將發放的薪資明細資料。" } }];
}

upcomingDates.sort((a, b) => new Date(a) - new Date(b));
const targetActualPayDate = upcomingDates[0]; 
const targetOriginalDate = dateMap[targetActualPayDate]; 

// 4. 尋找扣款表對應列
const targetDeductionRow = sheetDeductions.find(item => {
  const dDate = item.json["日期"] || item.json["col_21"] || "";
  return dDate === targetOriginalDate || dDate === targetActualPayDate;
});

// 5. 分組收集：完整收集 A ~ F 六組所有資料
const combinedGroups = {};

sheetDetails.forEach(item => {
  const data = item.json;
  const code = data["編號"];
  if (!code || typeof code !== 'string') return;

  const groupLetter = code.charAt(0).toUpperCase();
  if (!employeeConfig[groupLetter]) return;

  if (!combinedGroups[groupLetter]) {
    combinedGroups[groupLetter] = {
      actualPayDate: targetActualPayDate, 
      groupLetter: groupLetter,
      validRecords: [],
      unpaidRecords: []
    };
  }

  const payDateStr = String(data["發獎日期"] || "").trim();

  if (data["是否已發"] === "V" && payDateStr === targetOriginalDate) {
    combinedGroups[groupLetter].validRecords.push(data);
  } else if (!payDateStr) {
    const m_value = getRowSalary(data);
    if (m_value !== 0) {
      combinedGroups[groupLetter].unpaidRecords.push(data);
    }
  }
});

// 6. 表格 HTML 生成函數 (供 Gmail 使用，應領薪資改抓 M 欄/合計)
function buildTableHTML(records, tableTitle = "") {
  let total_account_fee = 0, total_other = 0, total_extra = 0, total_dividend = 0, total_settle = 0, total_salary = 0;
  let tableRowsHTML = "";

  records.forEach((data, index) => {
