    </table>

    ${emp.validTableHtml}
    ${unpaidTableHTML}
  </div>
  `;

  return {
    json: {
      pay_date: targetActualPayDate,
      employee_group: emp.group,
      employee_name: emp.name,
      employee_email: emp.email,
      html_table: finalHTML,
      tg_message: tgText,
      line_flex_json: commonLineFlex
    }
  };
});

// 1. 6 位同仁的真實姓名與專屬 Email 對照表
const employeeConfig = {
  "A": { name: "王淑娥", email: "ks111@kscpb.com" },
  "B": { name: "黃紋綺", email: "ks112@kscpb.com" },
  "C": { name: "張玉幸", email: "ks113@kscpb.com" },
  "D": { name: "黎依婷", email: "ks117@kscpb.com" },
  "E": { name: "余秋萍", email: "ks115@kscpb.com" },
  "F": { name: "周佳玲", email: "ks116@kscpb.com" }
};

// 向上追溯抓取完整原生資料
const sheetDetails = $('Get row(s) in sheet4').all();   // 明細表
const sheetDeductions = $('Get row(s) in sheet1').all(); // 扣款表

// 2. 自動提早發放機制 (遇假日提早至週五)
function getActualPayDate(dateStr) {
  if (!dateStr) return null;
  const dateParts = dateStr.split('/');
  if (dateParts.length !== 3) return null;

  let checkDate = new Date(parseInt(dateParts[0], 10), parseInt(dateParts[1], 10) - 1, parseInt(dateParts[2], 10));
  checkDate.setHours(0, 0, 0, 0);

  const dayOfWeek = checkDate.getDay();
  if (dayOfWeek === 6) checkDate.setDate(checkDate.getDate() - 1);
  else if (dayOfWeek === 0) checkDate.setDate(checkDate.getDate() - 2);

  return checkDate;
}

// 3. 計算目標發薪日
const today = new Date();
today.setHours(0, 0, 0, 0);

const validItems = sheetDetails.filter(item => item.json["是否已發"] === "V" && item.json["發獎日期"]);
const upcomingDates = [];
const dateMap = {}; 

validItems.forEach(item => {
  const originalDateStr = item.json["發獎日期"]; 
  const actualPayDate = getActualPayDate(originalDateStr);

  if (actualPayDate && actualPayDate >= today) {
    const yyyy = actualPayDate.getFullYear();
    const mm = String(actualPayDate.getMonth() + 1).padStart(2, '0');
    const dd = String(actualPayDate.getDate()).padStart(2, '0');
    const formattedKey = `${yyyy}/${mm}/${dd}`;

    if (!upcomingDates.includes(formattedKey)) upcomingDates.push(formattedKey);
    dateMap[formattedKey] = originalDateStr;
  }
});

if (upcomingDates.length === 0) {
  return [{ json: { message: "目前沒有未來即將發放的薪資明細資料。" } }];
}

upcomingDates.sort((a, b) => new Date(a) - new Date(b));
const targetActualPayDate = upcomingDates[0]; 
const targetOriginalDate = dateMap[targetActualPayDate]; 

// 4. 尋找扣款表對應列
const targetDeductionRow = sheetDeductions.find(item => {
  const dDate = item.json["日期"] || item.json["col_21"] || "";
  return dDate === targetOriginalDate || dDate === targetActualPayDate;
});

// 5. 分組收集：完整收集 A ~ F 六組所有資料
const combinedGroups = {};

sheetDetails.forEach(item => {
  const data = item.json;
  const code = data["編號"];
  if (!code || typeof code !== 'string') return;

  const groupLetter = code.charAt(0).toUpperCase();
  if (!employeeConfig[groupLetter]) return;

  if (!combinedGroups[groupLetter]) {
    combinedGroups[groupLetter] = {
      actualPayDate: targetActualPayDate, 
      groupLetter: groupLetter,
      validRecords: [],
      unpaidRecords: []
    };
  }

  const payDateStr = String(data["發獎日期"] || "").trim();

  if (data["是否已發"] === "V" && payDateStr === targetOriginalDate) {
    combinedGroups[groupLetter].validRecords.push(data);
  } else if (!payDateStr) {
    const account_fee = Number(data["帳費"]) || 0;
    const m_value = Number(data["應領薪資"]) || Number(data["薪資"]) || Math.round(account_fee * 0.4);
    if (m_value !== 0) {
      combinedGroups[groupLetter].unpaidRecords.push(data);
    }
  }
});

// 6. 表格 HTML 生成函數
function buildTableHTML(records, tableTitle = "") {
  let total_account_fee = 0, total_other = 0, total_extra = 0, total_dividend = 0, total_settle = 0, total_salary = 0;
  let tableRowsHTML = "";

  records.forEach((data, index) => {
    const account_fee = Number(data["帳費"]) || 0;
    const other = Number(data["其他"]) || 0;
    const extra = Number(data["加收補收"]) || 0;
    const dividend = Number(data["股利分配"]) || 0;
    const settle = Number(data["結算決算"]) || 0;
    const salary = Math.round(account_fee * 0.4); 

    total_account_fee += account_fee;
    total_other += other;
    total_extra += extra;
    total_dividend += dividend;
    total_settle += settle;
    total_salary += salary;

    const rawPeriod = data["期數"] || '';
    const formattedPeriod = rawPeriod.includes('/') ? rawPeriod.replace('/', '<br>') : rawPeriod;
    const rowBgColor = index % 2 === 1 ? 'background-color: #e0e0e0;' : 'background-color: #ffffff;';

    tableRowsHTML += `
      <tr style="${rowBgColor} font-size: 13pt;">
        <td style="border: 1px solid #000; padding: 6px; text-align: center; line-height: 1.2;">${formattedPeriod}</td>
        <td style="border: 1px solid #000; padding: 6px; text-align: center;">${data["編號"] || ''}</td>
        <td style="border: 1px solid #000; padding: 6px; text-align: left;">${data["客戶"] || ''}</td>
        <td style="border: 1px solid #000; padding: 6px; text-align: right;">${account_fee.toLocaleString()}</td>
        <td style="border: 1px solid #000; padding: 6px; text-align: right;">${other > 0 ? other.toLocaleString() : ''}</td>
        <td style="border: 1px solid #000; padding: 6px; text-align: right;">${extra > 0 ? extra.toLocaleString() : ''}</td>
        <td style="border: 1px solid #000; padding: 6px; text-align: right;">${dividend > 0 ? dividend.toLocaleString() : ''}</td>
        <td style="border: 1px solid #000; padding: 6px; text-align: right;">${settle > 0 ? settle.toLocaleString() : ''}</td>
        <td style="border: 1px solid #000; padding: 6px; text-align: right; font-weight: bold;">${salary.toLocaleString()}</td>
      </tr>
    `;
  });

  const titleHTML = tableTitle ? `<h3 style="margin-top: 25px; margin-bottom: 8px; font-size: 13pt; font-weight: bold; color: #000;">${tableTitle}</h3>` : '';

  const tableHTML = `
    ${titleHTML}
    <table style="width: 100%; border-collapse: collapse; text-align: center; border: 2px solid #000; table-layout: fixed;">
      <tr style="background-color: #ffffff; font-size: 13pt;">
        <th rowspan="2" style="border: 1px solid #000; padding: 8px; width: 8%; word-break: break-all;">年月</th>
        <th rowspan="2" style="border: 1px solid #000; padding: 8px; width: 4%; word-break: break-all;">編號</th>
        <th rowspan="2" style="border: 1px solid #000; padding: 8px; width: 28%; word-break: break-all;">客戶</th>
        <th style="border: 1px solid #000; padding: 4px; width: 10%;">帳費</th>
        <th style="border: 1px solid #000; padding: 4px; width: 10%;">其他</th>
        <th style="border: 1px solid #000; padding: 4px; width: 10%; line-height: 1.2;">加收<br>補收</th>
        <th style="border: 1px solid #000; padding: 4px; width: 10%; line-height: 1.2;">股利<br>分配</th>
        <th style="border: 1px solid #000; padding: 4px; width: 10%; line-height: 1.2;">結算<br>決算</th>
        <th style="border: 1px solid #000; padding: 4px; width: 10%; background-color: #ffffff; line-height: 1.2; font-weight: bold;">應領<br>薪資</th>
      </tr>
      <tr style="background-color: #ffffff; font-size: 13pt;">
        <td style="border: 1px solid #000; padding: 4px; text-align: right; font-weight: bold;">${total_account_fee.toLocaleString()}</td>
        <td style="border: 1px solid #000; padding: 4px; text-align: right; font-weight: bold;">${total_other > 0 ? total_other.toLocaleString() : '0'}</td>
        <td style="border: 1px solid #000; padding: 4px; text-align: right; font-weight: bold;">${total_extra > 0 ? total_extra.toLocaleString() : '0'}</td>
        <td style="border: 1px solid #000; padding: 4px; text-align: right; font-weight: bold;">${total_dividend > 0 ? total_dividend.toLocaleString() : '0'}</td>
        <td style="border: 1px solid #000; padding: 4px; text-align: right; font-weight: bold;">${total_settle > 0 ? total_settle.toLocaleString() : '0'}</td>
        <td style="border: 1px solid #000; padding: 4px; text-align: right; font-weight: bold;">${total_salary.toLocaleString()}</td>
      </tr>
      ${tableRowsHTML}
    </table>
  `;

  return { html: tableHTML, total_salary };
}

// 7. 產出 HTML 並封裝輸出（逐一為 A ~ F 組產出獨立資料）
const outputItems = [];

for (const group in combinedGroups) {
  const groupData = combinedGroups[group];
  const formattedDate = groupData.actualPayDate; 
  const validRecords = groupData.validRecords;
  const unpaidRecords = groupData.unpaidRecords;
  const config = employeeConfig[group];

  // 若該同仁本期無需要發放的明細，自動跳過不發信
  if (validRecords.length === 0) continue;

  const validTableRes = buildTableHTML(validRecords);
  const total_salary = validTableRes.total_salary;

  let labor_insurance = 0, health_insurance = 0, received_amount = 0, deduction_other = 0;

  if (targetDeductionRow) {
    const d = targetDeductionRow.json;
    labor_insurance = Number(d[`勞保${group}`]) || 0;  
    health_insurance = Number(d[`健保${group}`]) || 0; 
    received_amount = Number(d[`已領${group}`]) || 0; 
    deduction_other = Number(d[`其他${group}`]) || 0;
  }

  const actual_pay = total_salary + labor_insurance + health_insurance + received_amount + deduction_other;

  let unpaidTableHTML = "";
  if (unpaidRecords.length > 0) {
    const unpaidTableRes = buildTableHTML(unpaidRecords, "【尚未發放明細】");
    if (unpaidTableRes.total_salary !== 0) {
      unpaidTableHTML = unpaidTableRes.html;
    }
  }

  const finalHTML = `
  <div style="font-family: 'Microsoft JhengHei', Arial, sans-serif; max-width: 900px; margin: auto; padding: 10px; color: #000;">
    <p><b>${config.name}</b> 您好：以下為您客戶 <b>${group}</b> 於 <b>${formattedDate} (遇假日提早發放)</b> 之薪資明細總表。</p>

    <table style="width: 320px; border-collapse: collapse; margin-left: auto; margin-right: 0; margin-bottom: 30px; font-size: 13pt; border: 1px solid #d3d3d3; background-color: #fafafa;">
      <tr style="border-bottom: 1px solid #e0e0e0;">
        <td style="padding: 10px 15px; text-align: left; background-color: #f1f1f1; font-weight: bold; color: #333; width: 40%;">應領薪資</td>
        <td style="padding: 10px 15px; text-align: right; font-weight: bold; font-size: 14pt; color: #000;">${total_salary.toLocaleString()}</td>
      </tr>
      <tr style="border-bottom: 1px solid #e0e0e0;">
        <td style="padding: 8px 15px; text-align: left; background-color: #f9f9f9; color: #555;">勞保</td>
        <td style="padding: 8px 15px; text-align: right; color: red;">${labor_insurance !== 0 ? labor_insurance.toLocaleString() : '0'}</td>
      </tr>
      <tr style="border-bottom: 1px solid #e0e0e0;">
        <td style="padding: 8px 15px; text-align: left; background-color: #f9f9f9; color: #555;">健保</td>
        <td style="padding: 8px 15px; text-align: right; color: red;">${health_insurance !== 0 ? health_insurance.toLocaleString() : '0'}</td>
      </tr>
      <tr style="border-bottom: 1px solid #e0e0e0;">
        <td style="padding: 8px 15px; text-align: left; background-color: #f9f9f9; color: #555;">已領</td>
        <td style="padding: 8px 15px; text-align: right; color: red;">${received_amount !== 0 ? received_amount.toLocaleString() : '0'}</td>
      </tr>
      <tr style="border-bottom: 2px solid #333;">
        <td style="padding: 8px 15px; text-align: left; background-color: #f9f9f9; color: #555;">其他</td>
        <td style="padding: 8px 15px; text-align: right; color: ${deduction_other < 0 ? 'red' : 'black'};">${deduction_other !== 0 ? deduction_other.toLocaleString() : '0'}</td>
      </tr>
      <tr style="background-color: #edf2fa;">
        <td style="padding: 12px 15px; text-align: left; font-weight: bold; color: #002060; font-size: 14pt;">實發</td>
        <td style="padding: 12px 15px; text-align: right; font-weight: bold; font-size: 16pt; color: #002060;">${actual_pay.toLocaleString()}</td>
      </tr>
    </table>

    ${validTableRes.html}
    ${unpaidTableHTML}
  </div>
  `;

  outputItems.push({
    json: {
      pay_date: formattedDate,
      employee_group: group,
      employee_name: config.name,
      employee_email: config.email,
      html_table: finalHTML
    }
  });
}

return outputItems.length > 0 ? outputItems : [{ json: { message: "未找到符合當期發放條件的薪資明細資料。" } }];

// ==================== 1. 設定自訂特例 (可修改處) ====================
const customRules = [
  { date: "", timeRange: "1100~1700", title: "活動公告", content: "您好！為了提供更優質與合規的專業服務，本所同仁今日全體參加洗錢防制研習講座。專員將於明日上班後儘速與您回覆處理。" },
  { date: "", timeRange: "0800~1700", title: "颱風停班公告", content: "因颱風來襲，依縣市政府規定今日停止上班，期間訊息將於恢復上班後盡速處理。" }
];

function formatDateText(dateStr) {
  if (dateStr.length === 7) return `${dateStr.substring(0,3)}年${dateStr.substring(3,5)}月${dateStr.substring(5,7)}日`;
  if (dateStr.length === 8) return `${dateStr.substring(0,4)}年${dateStr.substring(4,6)}月${dateStr.substring(6,8)}日`;
  return dateStr;
}
function formatTimeText(timeRangeStr) {
  const times = timeRangeStr.split(/[~～\-]/).map(t => t.trim());
  if (times.length === 2 && times[0].length === 4 && times[1].length === 4) {
    return `${times[0].substring(0,2)}:${times[0].substring(2,4)}～${times[1].substring(0,2)}:${times[1].substring(2,4)}`;
  }
  return timeRangeStr;
}

const now = new Date();
const formatter = new Intl.DateTimeFormat('zh-TW', { timeZone: 'Asia/Taipei', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false });
const parts = Object.fromEntries(formatter.formatToParts(now).map(p => [p.type, p.value]));
const year = parseInt(parts.year), monthStr = parts.month, dayStr = parts.day;
const taipeiHour = parseInt(parts.hour) % 24, taipeiMinute = parseInt(parts.minute);
const currentHM = taipeiHour * 100 + taipeiMinute;
const currentDateCE = `${year}${monthStr}${dayStr}`;
const currentDateROC = `${year - 1911}${monthStr}${dayStr}`;

const result = $input.first().json;
const holidayInfo = Array.isArray(result) ? result[0] : result;
const isHoliday = holidayInfo ? holidayInfo.isHoliday : false;
const isOfficeHour = (taipeiHour >= 8 && taipeiHour < 17);
const isLunchBreak = (taipeiHour === 12);

let matchedCustomRule = null;
for (const rule of customRules) {
  if (!rule.date || rule.date.trim() === "") continue;
  if (rule.date === currentDateCE || rule.date === currentDateROC) {
    const times = rule.timeRange.split(/[~～\-]/).map(t => parseInt(t.trim()));
    if (times.length === 2) {
      const [startHM, endHM] = times;
      if (currentHM >= startHM && currentHM < endHM) { matchedCustomRule = rule; break; }
    }
  }
}

let displayTitle = "目前為非辦公時間";
let displayContent = "您好！感謝您的訊息。我們已收到您的資訊，將於下一個上班日優先處理，請耐心等候回覆。";
let heroImageUrl = "https://cdn-icons-png.flaticon.com/512/3652/3652191.png";
let isTriggered = false;

if (matchedCustomRule) {
  displayTitle = matchedCustomRule.title || "特別公告";
  displayContent = `【${formatDateText(matchedCustomRule.date)} ${formatTimeText(matchedCustomRule.timeRange)}】\n${matchedCustomRule.content}`;
  isTriggered = true;
} else if (isHoliday) {
  displayTitle = "今日為國定假日";
  displayContent = "您好！今日適逢假日，我們將於恢復上班後儘速處理您的訊息，祝您假期愉快。";
  isTriggered = true;
} else if (isLunchBreak) {
  displayTitle = "目前為午休時間";
  displayContent = "您好！目前正值午休時段，專員將於 13:00 過後盡速回覆您的訊息，謝謝您的耐心等候。";
  isTriggered = true;
} else if (!isOfficeHour) {
  isTriggered = true;
}

const flexMessage = {
  "type": "bubble", "direction": "ltr",
  "header": {"type": "box", "layout": "vertical", "contents": [{"type": "text", "text": "系統自動回覆", "weight": "bold", "color": "#1DB446", "size": "sm"}]},
  "hero": {"type": "image", "url": heroImageUrl, "size": "full", "aspectRatio": "20:13", "aspectMode": "cover"},
  "body": {"type": "box", "layout": "vertical", "contents": [
    {"type": "text", "text": displayTitle, "weight": "bold", "size": "xl", "wrap": true},
    {"type": "text", "text": displayContent, "margin": "lg", "size": "md", "color": "#666666", "wrap": true}
  ]},
  "footer": {"type": "box", "layout": "vertical", "contents": [{"text": "祝您有美好的一天！☀️", "type": "text", "style": "italic", "size": "sm", "color": "#aaaaaa", "align": "center"}]}
};

return {
  isOffWork: isTriggered,
  flexMessage: JSON.stringify(flexMessage),
  debugInfo: {
    currentCE: currentDateCE, currentROC: currentDateROC, currentHM: currentHM, isHoliday: isHoliday,
    customMatched: matchedCustomRule !== null,
    status: matchedCustomRule ? "CustomRule" : (isHoliday ? "Holiday" : (isLunchBreak ? "Lunch" : (isOfficeHour ? "OfficeHour" : "Off-work")))
  }
};

// 1. 取得全域靜態儲存區
const staticData = $getWorkflowStaticData('global');

// 2. 安全地取得 userId
let userId;
try {
  userId = $('Line Messaging Trigger').first().json.source.userId;
} catch (e) {
  userId = null;
}

const now = Date.now();
const COOLDOWN_MS = 5 * 60 * 1000; // 5 分鐘

if (!userId) {
  return { shouldReply: true, isNewId: false, reason: "No userId found", userId: "unknown" };
}

const isNewId = !staticData[userId];
const tgNotifyMessage = isNewId ? `🔔 偵測到新暫存寫入！\nID: ${userId}\n時間: ${new Date().toLocaleString('zh-TW', {timeZone: 'Asia/Taipei'})}` : null;

const lastReplyTime = staticData[userId];

if (lastReplyTime && (now - lastReplyTime < COOLDOWN_MS)) {
    return { shouldReply: false, isNewId: false, userId: userId, remainingTime: Math.round((COOLDOWN_MS - (now - lastReplyTime)) / 1000) + "s" };
} else {
    staticData[userId] = now;
    return { shouldReply: true, isNewId: isNewId, tgNotifyMessage: tgNotifyMessage, userId: userId };
}

const items = $input.all();
const faqMap = {};
const lines = [];

items.forEach((item, index) => {
  const rawCanAnswer = item.json['能否回答'];

  // 支援布林值 true、字串 'Y' 或 'TRUE'
  const isAllowed = rawCanAnswer === true || 
                    String(rawCanAnswer).trim().toUpperCase() === 'Y' || 
                    String(rawCanAnswer).trim().toUpperCase() === 'TRUE';

  if (isAllowed) {
    const id = String(item.json['row_number'] || (index + 2)).trim();
    const trigger = item.json['Trigger_Key (觸發關鍵字)'] || '';
    const related = item.json['Related_Keywords (關聯詞)'] || '';
    const jsonContent = item.json['JSON_Content (JSON 內容)'] || '';

    lines.push(`ID: ${id} | 關鍵字: ${trigger} | 關聯詞: ${related}`);

    if (jsonContent) {
      faqMap[id] = jsonContent;
    }
  }
});

return {
  faqText: lines.join('\n'),
  faqMap: faqMap
};

