parameters.jsCode:
const staticData = $getWorkflowStaticData('global');
const userId = $('Line Messaging Trigger').first().json.source.userId || 'unknown';
const now = Date.now();
const COOLDOWN_MS = 5 * 60 * 1000; // 5 分鐘冷卻

// 1. 取得時間判斷結果
const isOffWork = $('Check Time & Holiday Logic1').first().json.isOffWork;
const rawFlex = $('Check Time & Holiday Logic1').first().json.flexMessage;
const flexMessageJson = typeof rawFlex === 'string' ? JSON.parse(rawFlex) : rawFlex;

// 2. 取得前一節點（可回答/不可回答）傳進來的內容
const currentItem = $json;

// 3. 檢查離峰卡片冷卻狀態
const lastCardTime = staticData[`offwork_card_${userId}`] || 0;
const isCardInCooldown = (now - lastCardTime < COOLDOWN_MS);

const messages = [];

// 情境 A：下班時間 且 不在冷卻期 ➔ 包裝為標準 LINE Flex Message 並壓入
if (isOffWork && !isCardInCooldown) {
  messages.push({
    type: "flex",
    altText: flexMessageJson.body?.contents?.[0]?.text || "非辦公時間通知",
    contents: flexMessageJson
  });
  staticData[`offwork_card_${userId}`] = now;
}

// 情境 B：壓入回答內容（前一節點處理好的 Flex/Text 訊息）
if (currentItem.messageObject) {
  messages.push(currentItem.messageObject);
} else if (currentItem.replyText) {
  messages.push({
    type: "text",
    text: currentItem.replyText
  });
}

return {
  shouldSend: messages.length > 0,
  replyToken: $('Line Messaging Trigger').first().json.replyToken,
  messages: messages
};

const item = $input.first().json;

// 1. 取得 AI 回傳的 matchedId
const matchedId = item.output?.matchedId ?? item.matchedId;

// 2. 讀取「整理FAQ清單」產生的對照表
const faqData = $('整理FAQ清單1').first().json;
const faqMap = faqData.faqMap || {};

// 3. 取得第 69 列對應的 Flex JSON
const searchKey = String(matchedId).trim();
let rawFlex = faqMap[searchKey];

let messageObject;

if (rawFlex) {
  try {
    const parsedFlex = typeof rawFlex === 'string' ? JSON.parse(rawFlex) : rawFlex;

    // 打包成 LINE 標準 Flex Message 格式
    messageObject = {
      type: "flex",
      altText: "常見問題回覆",
      contents: parsedFlex
    };
  } catch (e) {
    messageObject = {
      type: "text",
      text: `Flex Message JSON 格式解析失敗：${e.message}`
    };
  }
} else {
  // 備用純文字
  messageObject = {
    type: "text",
    text: "感謝您的詢問，專員將於營業時間內盡快為您處理。"
  };
}

return { messageObject };

// 1. 取得全域靜態儲存區
const staticData = $getWorkflowStaticData('global');

// 2. 安全地取得 userId
let userId;
try {
  userId = $('Line Messaging Trigger').first().json.source.userId;
} catch (e) {
  userId = null;
}

const now = Date.now();
const COOLDOWN_MS = 5 * 60 * 1000; // 5 分鐘

if (!userId) {
  return { shouldReply: true, isNewId: false, reason: "No userId found", userId: "unknown" };
}

const isNewId = !staticData[userId];
const tgNotifyMessage = isNewId ? `🔔 偵測到新暫存寫入！\nID: ${userId}\n時間: ${new Date().toLocaleString('zh-TW', {timeZone: 'Asia/Taipei'})}` : null;

const lastReplyTime = staticData[userId];

if (lastReplyTime && (now - lastReplyTime < COOLDOWN_MS)) {
    return { shouldReply: false, isNewId: false, userId: userId, remainingTime: Math.round((COOLDOWN_MS - (now - lastReplyTime)) / 1000) + "s" };
} else {
    staticData[userId] = now;
    return { shouldReply: true, isNewId: isNewId, tgNotifyMessage: tgNotifyMessage, userId: userId };
}

const items = $input.all();
const faqMap = {};
const lines = [];

items.forEach((item, index) => {
  const rawCanAnswer = item.json['能否回答'];

  // 支援布林值 true、字串 'Y' 或 'TRUE'
  const isAllowed = rawCanAnswer === true || 
                    String(rawCanAnswer).trim().toUpperCase() === 'Y' || 
                    String(rawCanAnswer).trim().toUpperCase() === 'TRUE';

  if (isAllowed) {
    const id = String(item.json['row_number'] || (index + 2)).trim();
    const trigger = item.json['Trigger_Key (觸發關鍵字)'] || '';
    const related = item.json['Related_Keywords (關聯詞)'] || '';
    const jsonContent = item.json['JSON_Content (JSON 內容)'] || '';

    lines.push(`ID: ${id} | 關鍵字: ${trigger} | 關聯詞: ${related}`);

    if (jsonContent) {
      faqMap[id] = jsonContent;
    }
  }
});

return {
  faqText: lines.join('\n'),
  faqMap: faqMap
};

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "canAnswer": {
      "type": "boolean",
      "description": "問題是否在 FAQ 清單範圍內"
    },
    "matchedId": {
      "type": "number",
      "description": "清單中標示的指定 ID 數字（例如 69），請務必填寫實際 ID，勿填寫排序索引值 1"
    }
  },
  "required": [
    "canAnswer",
    "matchedId"
  ]
}

parameters.jsCode:
const staticData = $getWorkflowStaticData('global');
const userId = $('Line Messaging Trigger').first().json.source.userId || 'unknown';
const now = Date.now();
const COOLDOWN_MS = 5 * 60 * 1000; // 5 分鐘冷卻

// 1. 取得時間判斷結果
const isOffWork = $('Check Time & Holiday Logic').first().json.isOffWork;
const rawFlex = $('Check Time & Holiday Logic').first().json.flexMessage;
const flexMessageJson = typeof rawFlex === 'string' ? JSON.parse(rawFlex) : rawFlex;

// 2. 取得前一節點（可回答/不可回答）傳進來的內容
const currentItem = $json;

// 3. 檢查離峰卡片冷卻狀態
const lastCardTime = staticData[`offwork_card_${userId}`] || 0;
const isCardInCooldown = (now - lastCardTime < COOLDOWN_MS);

const messages = [];

// 情境 A：下班時間 且 不在冷卻期 ➔ 包裝為標準 LINE Flex Message 並壓入
if (isOffWork && !isCardInCooldown) {
  messages.push({
    type: "flex",
    altText: flexMessageJson.body?.contents?.[0]?.text || "非辦公時間通知",
    contents: flexMessageJson
  });
  staticData[`offwork_card_${userId}`] = now;
}

// 情境 B：壓入回答內容（前一節點處理好的 Flex/Text 訊息）
if (currentItem.messageObject) {
  messages.push(currentItem.messageObject);
} else if (currentItem.replyText) {
  messages.push({
    type: "text",
    text: currentItem.replyText
  });
}

return {
  shouldSend: messages.length > 0,
  replyToken: $('Line Messaging Trigger').first().json.replyToken,
  messages: messages
};

const rawOutput = $input.first().json.output || $input.first().json;
const canAnswer = rawOutput.canAnswer ?? false;
const matchType = rawOutput.matchType || "exact";

const faqData = $('整理FAQ清單2').first().json;
const faqMap = faqData.faqMap || {};

const groupActionNames = {
  "GROUP_SETUP": "設立流程",
  "GROUP_NAME_CHANGE": "名稱變更",
  "GROUP_BUSINESS_CHANGE": "營業項目變更",
  "GROUP_ADDRESS_CHANGE": "地址變更",
  "GROUP_PERSON_CHANGE": "負責人/董監事變更",
  "GROUP_CAPITAL_INCREASE": "增資",
  "GROUP_CAPITAL_DECREASE": "減資",
  "GROUP_SUSPEND": "停業",
  "GROUP_RESUME": "復業",
  "GROUP_DISSOLVE": "解散歇業",
  "GROUP_COPY": "抄錄/補發資料",
  "GROUP_OTHER": "其他變更"
};

function getFlexFromMap(id) {
  if (!id) return null;
  const rawKey = String(id).trim();
  const withSlash = rawKey.startsWith('/') ? rawKey : '/' + rawKey;
  const withoutSlash = rawKey.replace(/^\//, '');

  if (faqMap[rawKey]) return faqMap[rawKey];
  if (faqMap[withSlash]) return faqMap[withSlash];
  if (faqMap[withoutSlash]) return faqMap[withoutSlash];

  return null;
}

function formatPostbackData(id) {
  if (!id) return "";
  const str = String(id).trim();
  if (/^\d+$/.test(str)) {
    return '/' + str;
  }
  return str;
}

function safeParseJson(str) {
  if (!str) return null;
  if (typeof str === 'object') return str;
  try {
    const cleaned = String(str).replace(/[\r\n]+/g, ' ').trim();
    return JSON.parse(cleaned);
  } catch (e) {
    return null;
  }
}

function getShortLabel(label) {
  const str = String(label);
  if (str.includes("股份")) return "股份有限公司";
  if (str.includes("有限")) return "有限公司";
  if (str.includes("獨資")) return "獨資商業";
  if (str.includes("合夥")) return "合夥商業";
  return str.substring(0, 10);
}

// 輔助函式：即時檢查目前是否為非辦公時間
function checkIsOffWorkNow() {
  const now = new Date();
  const formatter = new Intl.DateTimeFormat('zh-TW', { 
    timeZone: 'Asia/Taipei', 
    weekday: 'short', 
    hour: '2-digit', 
    minute: '2-digit', 
    hour12: false 
  });
  const parts = Object.fromEntries(formatter.formatToParts(now).map(p => [p.type, p.value]));
  const weekday = parts.weekday;
  const hour = parseInt(parts.hour, 10);

  if (weekday === '週六' || weekday === '週日') return true;

  const isMorning = (hour >= 8 && hour < 12);
  const isAfternoon = (hour >= 13 && hour < 17);

  return !(isMorning || isAfternoon);
}

let messages = [];

if (canAnswer) {
  if (matchType === "ambiguous" && Array.isArray(rawOutput.options) && rawOutput.options.length > 0) {
    const triggerData = $('Line Messaging Trigger').first().json;
    const userText = triggerData.message?.text || triggerData.postback?.data || "";

    const companyKeywords = ["公司", "有限公司", "股份有限公司"];
    const businessKeywords = ["行號", "商業", "工作室", "店家", "企業社", "商行", "店面"];

    const hasCompanyWord = companyKeywords.some(kw => userText.includes(kw));
    const hasBusinessWord = businessKeywords.some(kw => userText.includes(kw));

    const isCompanyOnly = hasCompanyWord && !hasBusinessWord;
    const isBusinessOnly = hasBusinessWord && !hasCompanyWord;

    let filteredOptions = rawOutput.options;

    if (isCompanyOnly) {
      filteredOptions = filteredOptions.filter(opt => {
        const idStr = formatPostbackData(opt.id);
        const labelStr = String(opt.label);
        return idStr.startsWith('/10') || idStr.startsWith('/20') || labelStr.includes("有限") || labelStr.includes("股份");
      });
    } else if (isBusinessOnly) {
      filteredOptions = filteredOptions.filter(opt => {
        const idStr = formatPostbackData(opt.id);
        const labelStr = String(opt.label);
        return idStr.startsWith('/30') || idStr.startsWith('/40') || labelStr.includes("獨資") || labelStr.includes("合夥");
      });
    }

    if (filteredOptions.length === 0) {
      filteredOptions = rawOutput.options;
    }

    const groupKey = rawOutput.ambiguousGroup || "";
    const standardAction = groupActionNames[groupKey] || rawOutput.actionName || "變更事項";
    const promptText = `請問您是指哪種組織型態的『${standardAction}』？`;

    messages.push({
      type: "text",
      text: promptText,
      quickReply: {
        items: filteredOptions.slice(0, 13).map(opt => {
          const displayLabel = getShortLabel(opt.label);
          return {
            type: "action",
            action: {
              type: "postback",
              label: displayLabel,
              displayText: displayLabel,
              data: formatPostbackData(opt.id)
            }
          };
        })
      }
    });

  } else if (matchType === "exact" || rawOutput.matchedId) {
    const targetId = String(rawOutput.matchedId || "").trim();
    const userText = $('Line Messaging Trigger').first().json.message?.text || "";

    const isDirectCommand = userText.startsWith('/');
    const isVagueReportQuery = targetId === "索取資料模糊" || targetId === "報表";

    const documentKeywords = ["401", "營業稅申報書", "公司登記表", "結算報表", "結算申報書", "公司章程", "商業抄本"];
    const isSpecificDocQuery = documentKeywords.some(kw => userText.includes(kw));

    if (isVagueReportQuery && !isDirectCommand) {
      messages.push({
        type: "text",
        text: "「客戶資料夾」是儲存已經產生的資料 (包含：401表、結算申報書、公司登記表、公司章程、商業抄本等等)。\n\n請問您是指哪一項？",
        quickReply: {
          items: [
            {
              type: "action",
              action: {
                type: "message",
                label: "📁 客戶資料夾",
                text: "客戶資料夾"
              }
            },
            {
              type: "action",
              action: {
                type: "message",
                label: "📊 暫結報表",
                text: "我要暫結報表"
              }
            }
          ]
        }
      });
    } else if (isSpecificDocQuery && !isDirectCommand) {
      messages.push({
        type: "text",
        text: "以上文件請點下方快速回覆按鈕或輸入客戶資料夾",
        quickReply: {
          items: [
            {
              type: "action",
              action: {
                type: "message",
                label: "📁 客戶資料夾",
                text: "客戶資料夾"
              }
            }
          ]
        }
      });
    } else {
      let rawFlex = getFlexFromMap(targetId);

      if (rawFlex) {
        const flexContent = safeParseJson(rawFlex);

        if (flexContent) {
          messages.push({
            type: "flex",
            altText: flexContent.altText || "常見問題與服務回覆",
            contents: flexContent.type === "bubble" || flexContent.type === "carousel" 
                      ? flexContent 
                      : (flexContent.contents || flexContent)
          });
        }
      } else {
        // 🛡️ 找不到卡片時：判定是否為非上班時間
        const isOffWork = checkIsOffWorkNow();

        if (isOffWork) {
          // 引入冷卻時間機制 (5分鐘)
          const staticData = $getWorkflowStaticData('global');
          const triggerData = $('Line Messaging Trigger').first().json;
          const userId = triggerData.source?.userId || 'unknown';

          const now = Date.now();
          const COOLDOWN_MS = 5 * 60 * 1000; // 5分鐘冷卻
          const lastReplyTime = staticData[userId] || 0;
          const isInCooldown = (now - lastReplyTime) < COOLDOWN_MS;

          if (!isInCooldown) {
            staticData[userId] = now; // 更新最後回覆時間

            // 抓取下班公告卡片
            const offWorkFlex = $('Check Time & Holiday Logic2').first().json.flexMessage;
            const offWorkJson = typeof offWorkFlex === 'string' ? JSON.parse(offWorkFlex) : offWorkFlex;

            messages.push({
              type: "flex",
              altText: "非辦公時間通知",
              contents: offWorkJson
            });
          }
          // 如果 isInCooldown 為 true，messages 保持空陣列，LINE 就不會發送訊息洗版！
        } else {
          // 上班時間找不到卡片：保持空白，留給真人處理
        }
      }
    }
  }
}

return {
  shouldSend: messages.length > 0,
  messages: messages
};

const rawFlex = $('Check Time & Holiday Logic2').first().json.flexMessage;
const flexMessageJson = typeof rawFlex === 'string' ? JSON.parse(rawFlex) : rawFlex;

return {
  messages: [
    {
      type: "flex",
      altText: flexMessageJson.body?.contents?.[0]?.text || "非辦公時間通知",
      contents: flexMessageJson
    }
  ]
};

const customRules = [
  // 颱風假範例 (全天停班：isAllDay 設為 true，不用寫時間)
  { date: "20260907", isAllDay: true, title: "颱風停班公告", badgeText: "🌀 颱風停班", content: "因颱風來襲，依縣市政府規定本日（{DATE}）停止上班上課。期間訊息將於恢復上班後儘速為您處理，造成不便敬請見諒。" },

  // 特定時段活動公告範例 (時段性：填寫 timeRange)
  { date: "", timeRange: "", title: "活動公告", badgeText: "📢 特別公告", content: "您好！為了提供更優質與合規的專業服務，本所同仁今日全體參加洗錢防制研習講座。專員將於明日上班後儘速與您回覆處理。" }
];

function formatDateText(dateStr) {
  if (dateStr.length === 7) return `${dateStr.substring(0,3)}年${dateStr.substring(3,5)}月${dateStr.substring(5,7)}日`;
  if (dateStr.length === 8) return `${dateStr.substring(0,4)}年${dateStr.substring(4,6)}月${dateStr.substring(6,8)}日`;
  return dateStr;
}
function formatTimeText(timeRangeStr) {
  if (!timeRangeStr) return "";
  const times = timeRangeStr.split(/[~～\-]/).map(t => t.trim());
  if (times.length === 2 && times[0].length === 4 && times[1].length === 4) {
    return `${times[0].substring(0,2)}:${times[0].substring(2,4)}～${times[1].substring(0,2)}:${times[1].substring(2,4)}`;
  }
  return timeRangeStr;
}

const now = new Date();
const formatter = new Intl.DateTimeFormat('zh-TW', { timeZone: 'Asia/Taipei', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false });
const parts = Object.fromEntries(formatter.formatToParts(now).map(p => [p.type, p.value]));
const year = parseInt(parts.year), monthStr = parts.month, dayStr = parts.day;
const taipeiHour = parseInt(parts.hour) % 24, taipeiMinute = parseInt(parts.minute);
const currentHM = taipeiHour * 100 + taipeiMinute;
const currentDateCE = `${year}${monthStr}${dayStr}`;
const currentDateROC = `${year - 1911}${monthStr}${dayStr}`;

const result = $input.first().json;
const holidayInfo = Array.isArray(result) ? result[0] : result;
const isHoliday = holidayInfo ? holidayInfo.isHoliday : false;
const isOfficeHour = (taipeiHour >= 8 && taipeiHour < 17);
const isLunchBreak = (taipeiHour === 12);

let matchedCustomRule = null;
for (const rule of customRules) {
  if (!rule.date || rule.date.trim() === "") continue;
  if (rule.date === currentDateCE || rule.date === currentDateROC) {
    if (rule.isAllDay) {
      matchedCustomRule = rule;
      break;
    } else if (rule.timeRange) {
      const times = rule.timeRange.split(/[~～\-]/).map(t => parseInt(t.trim()));
      if (times.length === 2) {
        const [startHM, endHM] = times;
        if (currentHM >= startHM && currentHM < endHM) { matchedCustomRule = rule; break; }
      }
    }
  }
}

// 預設樣式（非辦公時間）
let displayTitle = "目前為非辦公時間";
let displayContent = "您好！感謝您的訊息。我們已收到您的資訊，將於下一個上班日優先處理，請耐心等候回覆。";
let badgeText = "🌙 非營業時間";
let badgeColor = "#283593";
let badgeBg = "#E8EAF6";
let themeColor = "#3F51B5";
let isTriggered = false;

if (matchedCustomRule) {
  const formattedDate = formatDateText(matchedCustomRule.date);
  displayTitle = matchedCustomRule.title || "特別公告";
  badgeText = matchedCustomRule.badgeText || "📢 特別公告";
  badgeColor = "#C62828";
  badgeBg = "#FFEBEE";
  themeColor = "#D32F2F";

  if (matchedCustomRule.isAllDay) {
    // 全天公告（動態將 {DATE} 替換為日期文字）
    displayContent = matchedCustomRule.content.replace("{DATE}", formattedDate);
  } else {
    // 特定時段公告
    displayContent = `【${formattedDate} ${formatTimeText(matchedCustomRule.timeRange)}】\n${matchedCustomRule.content}`;
  }
  isTriggered = true;
} else if (isHoliday) {
  displayTitle = "今日為國定假日";
  displayContent = "您好！今日適逢國定假日，我們將於恢復上班後儘速處理您的訊息，祝您假期愉快。";
  badgeText = "🎉 國定假日";
  badgeColor = "#00695C";
  badgeBg = "#E0F2F1";
  themeColor = "#00897B";
  isTriggered = true;
} else if (isLunchBreak) {
  displayTitle = "目前為午休時間";
  displayContent = "您好！目前正值午休時段，專員將於 13:00 過後盡速回覆您的訊息，謝謝您的耐心等候。";
  badgeText = "🍱 午休時段";
  badgeColor = "#E65100";
  badgeBg = "#FFF3E0";
  themeColor = "#EF6C00";
  isTriggered = true;
} else if (!isOfficeHour) {
  isTriggered = true;
}

// 服務時間資訊區塊
const serviceHoursBox = {
  "type": "box",
  "layout": "vertical",
  "margin": "lg",
  "spacing": "sm",
  "backgroundColor": "#F8F9FA",
  "paddingAll": "md",
  "cornerRadius": "lg",
  "borderColor": "#EAEAEA",
  "borderWidth": "1px",
  "contents": [
    { "type": "text", "text": "🕒 事務所服務時間", "weight": "bold", "size": "sm", "color": "#333333" },
    { "type": "separator", "margin": "xs", "color": "#EAEAEA" },
    {
      "type": "box",
      "layout": "horizontal",
      "margin": "sm",
      "contents": [
        { "type": "text", "text": "📅 服務日期", "size": "sm", "color": "#777777", "flex": 3 },
        { "type": "text", "text": "每週一至週五", "size": "sm", "color": "#222222", "weight": "bold", "flex": 5 }
      ]
    },
    {
      "type": "box",
      "layout": "horizontal",
      "contents": [
        { "type": "text", "text": "⏰ 服務時段", "size": "sm", "color": "#777777", "flex": 3 },
        { "type": "text", "text": "08:00～12:00\n13:00～17:00", "size": "sm", "color": "#222222", "wrap": true, "flex": 5 }
      ]
    },
    {
      "type": "box",
      "layout": "horizontal",
      "contents": [
        { "type": "text", "text": "📢 休假說明", "size": "sm", "color": "#777777", "flex": 3 },
        { "type": "text", "text": "國定假日與例假日依行政院人事行政總處公告放假", "size": "xs", "color": "#666666", "wrap": true, "flex": 5 }
      ]
    }
  ]
};

const flexMessage = {
  "type": "bubble",
  "direction": "ltr",
  "header": {
    "type": "box",
    "layout": "horizontal",
    "contents": [
      { "type": "text", "text": "系統自動回覆", "weight": "bold", "color": "#1DB446", "size": "xs", "gravity": "center" },
      {
        "type": "box",
        "layout": "horizontal",
        "contents": [
          { "type": "text", "text": badgeText, "size": "xs", "color": badgeColor, "weight": "bold", "align": "center" }
        ],
        "backgroundColor": badgeBg,
        "cornerRadius": "20px",
        "paddingAll": "xs",
        "paddingStart": "md",
        "paddingEnd": "md"
      }
    ]
  },
  "body": {
    "type": "box",
    "layout": "vertical",
    "spacing": "md",
    "contents": [
      {
        "type": "box",
        "layout": "horizontal",
        "spacing": "md",
        "contents": [
          {
            "type": "box",
            "layout": "vertical",
            "contents": [],
            "width": "4px",
            "backgroundColor": themeColor,
            "cornerRadius": "2px"
          },
          { "type": "text", "text": displayTitle, "weight": "bold", "size": "xl", "color": "#111111", "wrap": true }
        ]
      },
      { "type": "text", "text": displayContent, "size": "sm", "color": "#555555", "wrap": true },
      serviceHoursBox
    ]
  },
  "footer": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      { "text": "祝您有美好的一天！☀️", "type": "text", "style": "italic", "size": "sm", "color": "#AAAAAA", "align": "center" }
    ]
  }
};

return {
  isOffWork: isTriggered,
  flexMessage: JSON.stringify(flexMessage)
};

// ==================== 1. 設定自訂特例 (可修改處) ====================
const customRules = [
  { date: "", timeRange: "1100~1700", title: "活動公告", content: "您好！為了提供更優質與合規的專業服務，本所同仁今日全體參加洗錢防制研習講座。專員將於明日上班後儘速與您回覆處理。" },
  { date: "", timeRange: "0800~1700", title: "颱風停班公告", content: "因颱風來襲，依縣市政府規定今日停止上班，期間訊息將於恢復上班後盡速處理。" }
];

function formatDateText(dateStr) {
  if (dateStr.length === 7) return `${dateStr.substring(0,3)}年${dateStr.substring(3,5)}月${dateStr.substring(5,7)}日`;
  if (dateStr.length === 8) return `${dateStr.substring(0,4)}年${dateStr.substring(4,6)}月${dateStr.substring(6,8)}日`;
  return dateStr;
}
function formatTimeText(timeRangeStr) {
  const times = timeRangeStr.split(/[~～\-]/).map(t => t.trim());
  if (times.length === 2 && times[0].length === 4 && times[1].length === 4) {
    return `${times[0].substring(0,2)}:${times[0].substring(2,4)}～${times[1].substring(0,2)}:${times[1].substring(2,4)}`;
  }
  return timeRangeStr;
}

const now = new Date();
const formatter = new Intl.DateTimeFormat('zh-TW', { timeZone: 'Asia/Taipei', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false });
const parts = Object.fromEntries(formatter.formatToParts(now).map(p => [p.type, p.value]));
const year = parseInt(parts.year), monthStr = parts.month, dayStr = parts.day;
const taipeiHour = parseInt(parts.hour) % 24, taipeiMinute = parseInt(parts.minute);
const currentHM = taipeiHour * 100 + taipeiMinute;
const currentDateCE = `${year}${monthStr}${dayStr}`;
const currentDateROC = `${year - 1911}${monthStr}${dayStr}`;

const result = $input.first().json;
const holidayInfo = Array.isArray(result) ? result[0] : result;
const isHoliday = holidayInfo ? holidayInfo.isHoliday : false;
const isOfficeHour = (taipeiHour >= 8 && taipeiHour < 17);
const isLunchBreak = (taipeiHour === 12);

let matchedCustomRule = null;
for (const rule of customRules) {
  if (!rule.date || rule.date.trim() === "") continue;
  if (rule.date === currentDateCE || rule.date === currentDateROC) {
    const times = rule.timeRange.split(/[~～\-]/).map(t => parseInt(t.trim()));
    if (times.length === 2) {
      const [startHM, endHM] = times;
      if (currentHM >= startHM && currentHM < endHM) { matchedCustomRule = rule; break; }
    }
  }
}

let displayTitle = "目前為非辦公時間";
let displayContent = "您好！感謝您的訊息。我們已收到您的資訊，將於下一個上班日優先處理，請耐心等候回覆。";
let heroImageUrl = "https://cdn-icons-png.flaticon.com/512/3652/3652191.png";
let isTriggered = false;

if (matchedCustomRule) {
  displayTitle = matchedCustomRule.title || "特別公告";
  displayContent = `【${formatDateText(matchedCustomRule.date)} ${formatTimeText(matchedCustomRule.timeRange)}】\n${matchedCustomRule.content}`;
  isTriggered = true;
} else if (isHoliday) {
  displayTitle = "今日為國定假日";
  displayContent = "您好！今日適逢假日，我們將於恢復上班後儘速處理您的訊息，祝您假期愉快。";
  isTriggered = true;
} else if (isLunchBreak) {
  displayTitle = "目前為午休時間";
  displayContent = "您好！目前正值午休時段，專員將於 13:00 過後盡速回覆您的訊息，謝謝您的耐心等候。";
  isTriggered = true;
} else if (!isOfficeHour) {
  isTriggered = true;
}

const flexMessage = {
  "type": "bubble", "direction": "ltr",
  "header": {"type": "box", "layout": "vertical", "contents": [{"type": "text", "text": "系統自動回覆", "weight": "bold", "color": "#1DB446", "size": "sm"}]},
  "hero": {"type": "image", "url": heroImageUrl, "size": "full", "aspectRatio": "20:13", "aspectMode": "cover"},
  "body": {"type": "box", "layout": "vertical", "contents": [
    {"type": "text", "text": displayTitle, "weight": "bold", "size": "xl", "wrap": true},
    {"type": "text", "text": displayContent, "margin": "lg", "size": "md", "color": "#666666", "wrap": true}
  ]},
  "footer": {"type": "box", "layout": "vertical", "contents": [{"text": "祝您有美好的一天！☀️", "type": "text", "style": "italic", "size": "sm", "color": "#aaaaaa", "align": "center"}]}
};

return {
  isOffWork: isTriggered,
  flexMessage: JSON.stringify(flexMessage),
  debugInfo: {
    currentCE: currentDateCE, currentROC: currentDateROC, currentHM: currentHM, isHoliday: isHoliday,
    customMatched: matchedCustomRule !== null,
    status: matchedCustomRule ? "CustomRule" : (isHoliday ? "Holiday" : (isLunchBreak ? "Lunch" : (isOfficeHour ? "OfficeHour" : "Off-work")))
  }
};

const staticData = $getWorkflowStaticData('global');

let userId, userText;
try {
  const triggerData = $('Line Messaging Trigger').first().json;
  userId = triggerData.source?.userId || 'unknown';
  userText = triggerData.message?.text || '[非文字訊息/貼圖]';
} catch (e) {
  userId = 'unknown';
  userText = '[解析失敗]';
}

const now = Date.now();
const COOLDOWN_MS = 5 * 60 * 1000; // 5 分鐘冷卻期

const lastReplyTime = staticData[userId] || 0;
const isInCooldown = (now - lastReplyTime) < COOLDOWN_MS;

// 格式化台北時間
const timeStr = new Date().toLocaleString('zh-TW', { timeZone: 'Asia/Taipei' });

// 1. 每次下班時間有人傳訊息，都組合 Telegram 紀錄文字
const tgNotifyMessage = `🌙 <b>【下班時間客戶留言】</b>\n` +
  `<b>時間：</b>${timeStr}\n` +
  `<b>User ID：</b><code>${userId}</code>\n` +
  `<b>留言內容：</b>${userText}\n` +
  `<b>LINE 回覆狀態：</b>${isInCooldown ? '🔇 冷卻中（不重覆發送罐頭訊息）' : '✅ 已發送下班回覆'}`;

// 2. 若不在冷卻期，更新最後回覆時間
if (!isInCooldown) {
  staticData[userId] = now;
}

return {
  shouldReplyLine: !isInCooldown, // true 代表 LINE 要發送罐頭訊息
  tgNotifyMessage: tgNotifyMessage,
  userId: userId
};

const items = $input.all();
const faqMap = {};
const lines = [];

items.forEach((item, index) => {
  const rawCanAnswer = item.json['能否回答'];

  const isAllowed = rawCanAnswer === true || 
                    String(rawCanAnswer).trim().toUpperCase() === 'Y' || 
                    String(rawCanAnswer).trim().toUpperCase() === 'TRUE';

  if (isAllowed) {
    const id = String(item.json['row_number'] || (index + 2)).trim();
    const trigger = String(item.json['Trigger_Key (觸發關鍵字)'] || '').trim();
    const related = String(item.json['Related_Keywords (關聯詞)'] || '').trim();
    const jsonContent = item.json['JSON_Content (JSON 內容)'] || '';

    lines.push(`ID: ${id} | 關鍵字: ${trigger} | 關聯詞: ${related}`);

    if (jsonContent) {
      // 1. 以列號 ID 當 Key（例如 "69"）
      faqMap[id] = jsonContent;

      // 2. 同時將觸發關鍵字當 Key（例如 "/報價單" 與 "報價單"）
      if (trigger) {
        faqMap[trigger] = jsonContent;
        const withSlash = trigger.startsWith('/') ? trigger : '/' + trigger;
        const withoutSlash = trigger.replace(/^\//, '');
        faqMap[withSlash] = jsonContent;
        faqMap[withoutSlash] = jsonContent;
      }
    }
  }
});

return {
  faqText: lines.join('\n'),
  faqMap: faqMap
};

