let llms = await this.getInputConnectionData('ai_languageModel', 0);

const llm_index = $input.item.json.fail_count;

if (!Number.isInteger(llm_index)) {
  console.log("'llm_index' is undefined or not a valid integer");
  throw new Error("'llm_index' is undefined or not a valid integer");
}

// 印出目前抓到的所有模型，方便你確認每一顆的識別資訊長怎樣
console.log('抓到的模型數量:', llms.length);
llms.forEach((m, i) => {
  console.log(`原始 index ${i}:`, JSON.stringify({
    model: m?.lc_kwargs?.model,
    credentialId: m?.lc_kwargs?.credentials?.googlePalmApi?.id || m?.lc_kwargs?.apiKey,
  }));
});

// 🚨 依你要的優先順序，明確指定 credential ID（先免費，失敗才用付費）
const PRIORITY_CREDENTIAL_IDS = [
  'IHjq0LOB09T8Z2WC', // 免費帳號 Google Gemini Api FREE tier → 優先
  'lKLBDs2wR4pbmIVu', // 付費帳號 Google Gemini Api Tier1 → 備援
];

llms.sort((a, b) => {
  const aId = a?.lc_kwargs?.credentials?.googlePalmApi?.id;
  const bId = b?.lc_kwargs?.credentials?.googlePalmApi?.id;
  return PRIORITY_CREDENTIAL_IDS.indexOf(aId) - PRIORITY_CREDENTIAL_IDS.indexOf(bId);
});

console.log('排序後，本次選中的 index:', llm_index);

if (typeof llms[llm_index] === 'undefined') {
  console.log(`No LLM found with index ${llm_index}`);
  throw new Error(`No LLM found with index ${llm_index}`);
}

return llms[llm_index];
